screenPanels.initJs:
function(container, apiUrl, tables) {
  // 店舗データの初期化
  const storeSelect = container.querySelector("#store-select");
  const storeTable = tables.find(t => t.tableName === "店舗マスタ");
  if (storeTable && storeTable.records) {
    storeTable.records.forEach(store => {
      if (store.有効フラグ) {
        const option = document.createElement("option");
        option.value = store.店舗ID;
        option.textContent = `${store.店舗コード} - ${store.店舗名}`;
        storeSelect.appendChild(option);
      }
    });
  }

  // 需要予測結果テーブルの再描画関数
  function renderPredictionRows(rows) {
    const tbody = container.querySelector("#prediction-list");
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.予測結果ID || r.id}">
        <td>${r.商品コード || "-"}</td>
        <td>${r.商品名 || "-"}</td>
        <td>${r.予測対象日 ? new Date(r.予測対象日).toLocaleDateString() : "-"}</td>
        <td>${r.予測数量 || 0}</td>
        <td>${r.予測精度 || 0}%</td>
        <td>${r.推奨発注数量 || 0}</td>
        <td>
          <span style="padding: 0.2rem 0.5rem; border-radius: 4px; font-size: 0.8rem; 
                       background: ${r.予測ステータス === '完了' ? '#28a745' : r.予測ステータス === 'エラー' ? '#dc3545' : '#ffc107'}; 
                       color: white;">
            ${r.予測ステータス || "未実行"}
          </span>
        </td>
        <td>
          <button class="action-btn secondary detail-btn" data-id="${r.予測結果ID || r.id}">詳細</button>
          <button class="action-btn secondary delete-btn" data-id="${r.予測結果ID || r.id}">削除</button>
        </td>
      </tr>
    `).join("");
  }

  // 初期データの描画
  const predictionTableIndex = tables.findIndex(t => t.tableName === "需要予測結果");
  if (predictionTableIndex >= 0) {
    renderPredictionRows(tables[predictionTableIndex].records || []);
  }

  // エラー表示関数
  function showError(message) {
    const errorDiv = container.querySelector("#error-message");
    const errorText = container.querySelector("#error-text");
    errorText.textContent = message;
    errorDiv.classList.remove("hidden");
    setTimeout(() => errorDiv.classList.add("hidden"), 5000);
  }

  // 処理中表示関数
  function showProcessing(show) {
    const processingDiv = container.querySelector("#processing-message");
    if (show) {
      processingDiv.classList.remove("hidden");
    } else {
      processingDiv.classList.add("hidden");
    }
  }

  // 予測結果表示関数
  function showPredictionResults() {
    const resultsDiv = container.querySelector("#prediction-results");
    resultsDiv.classList.remove("hidden");

    // サンプルデータで予測精度指標を更新
    container.querySelector("#accuracy-score").textContent = "87.5%";
    container.querySelector("#confidence-level").textContent = "92.3%";
    container.querySelector("#model-version").textContent = "v2.1.0";

    // 影響要因分析結果を更新
    container.querySelector("#seasonal-impact").textContent = "中程度 (+15%)";
    container.querySelector("#weather-impact").textContent = "高 (+25%)";
    container.querySelector("#event-impact").textContent = "低 (+3%)";

    // 天候・イベント情報を更新
    container.querySelector("#weather-forecast").textContent = "晴れ時々曇り";
    container.querySelector("#scheduled-events").textContent = "地域祭り (3日後)";

    // グラフを描画
    drawPredictionChart();
    drawComparisonChart();
  }

  // 予測グラフ描画関数
  function drawPredictionChart() {
    const canvas = container.querySelector("#prediction-chart");
    const ctx = canvas.getContext("2d");

    // Canvas サイズ設定
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width;
    canvas.height = rect.height;

    // グラフエリア設定
    const padding = 60;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    // 背景クリア
    ctx.fillStyle = '#1a2a4a';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // サンプルデータ
    const days = 7;
    const actualData = [120, 135, 98, 156, 142, 189, 167];
    const predictedData = [125, 140, 95, 160, 145, 185, 170];

    // Y軸の最大値
    const maxValue = Math.max(...actualData, ...predictedData) * 1.2;

    // グリッド線描画
    ctx.strokeStyle = '#3a4a6a';
    ctx.lineWidth = 1;

    // 横線
    for (let i = 0; i <= 5; i++) {
      const y = padding + (chartHeight / 5) * i;
      ctx.beginPath();
      ctx.moveTo(padding, y);
      ctx.lineTo(padding + chartWidth, y);
      ctx.stroke();
    }

    // 縦線
    for (let i = 0; i <= days - 1; i++) {
      const x = padding + (chartWidth / (days - 1)) * i;
      ctx.beginPath();
      ctx.moveTo(x, padding);
      ctx.lineTo(x, padding + chartHeight);
      ctx.stroke();
    }

    // 実績データ線
    ctx.strokeStyle = '#28a745';
    ctx.lineWidth = 3;
    ctx.beginPath();
    for (let i = 0; i < actualData.length; i++) {
      const x = padding + (chartWidth / (days - 1)) * i;
      const y = padding + chartHeight - (actualData[i] / maxValue) * chartHeight;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // 予測データ線
    ctx.strokeStyle = '#007bff';
    ctx.lineWidth = 3;
    ctx.setLineDash([5, 5]);
    ctx.beginPath();
    for (let i = 0; i < predictedData.length; i++) {
      const x = padding + (chartWidth / (days - 1)) * i;
      const y = padding + chartHeight - (predictedData[i] / maxValue) * chartHeight;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();
    ctx.setLineDash([]);

    // ラベル描画
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '12px sans-serif';
    ctx.textAlign = 'center';

    // X軸ラベル
    for (let i = 0; i < days; i++) {
      const x = padding + (chartWidth / (days - 1)) * i;
      const date = new Date();
      date.setDate(date.getDate() + i);
      ctx.fillText(date.toLocaleDateString('ja-JP', { month: 'numeric', day: 'numeric' }), x, canvas.height - 20);
    }

    // Y軸ラベル
    ctx.textAlign = 'right';
    for (let i = 0; i <= 5; i++) {
      const y = padding + (chartHeight / 5) * i;
      const value = Math.round(maxValue * (1 - i / 5));
      ctx.fillText(value.toString(), padding - 10, y + 4);
    }

    // 凡例
    ctx.textAlign = 'left';
    ctx.fillStyle = '#28a745';
    ctx.fillRect(padding, 20, 20, 3);
    ctx.fillStyle = '#9fb0d1';
    ctx.fillText('実績', padding + 30, 30);

    ctx.fillStyle = '#007bff';
    ctx.fillRect(padding + 100, 20, 20, 3);
    ctx.fillStyle = '#9fb0d1';
    ctx.fillText('予測', padding + 130, 30);
  }

  // 比較グラフ描画関数
  function drawComparisonChart() {
    const canvas = container.querySelector("#comparison-chart");
    const ctx = canvas.getContext("2d");

    // Canvas サイズ設定
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width;
    canvas.height = rect.height;

    // 背景クリア
    ctx.fillStyle = '#1a2a4a';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // サンプル比較データ（棒グラフ）
    const categories = ['食品', '飲料', '日用品', '冷凍食品'];
    const actualValues = [85, 92, 78, 88];
    const predictedValues = [87, 89, 82, 85];

    const padding = 60;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;
    const barWidth = chartWidth / (categories.length * 3);

    // 最大値
    const maxValue = 100;

    // 棒グラフ描画
    categories.forEach((category, i) => {
      const x = padding + i * (chartWidth / categories.length);

      // 実績棒
      const actualHeight = (actualValues[i] / maxValue) * chartHeight;
      ctx.fillStyle = '#28a745';
      ctx.fillRect(x + barWidth * 0.2, padding + chartHeight - actualHeight, barWidth * 0.8, actualHeight);

      // 予測棒
      const predictedHeight = (predictedValues[i] / maxValue) * chartHeight;
      ctx.fillStyle = '#007bff';
      ctx.fillRect(x + barWidth * 1.2, padding + chartHeight - predictedHeight, barWidth * 0.8, predictedHeight);

      // カテゴリラベル
      ctx.fillStyle = '#9fb0d1';
      ctx.font = '12px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(category, x + barWidth, canvas.height - 20);
    });
  }

  // バリデーション関数
  function validatePredictionForm() {
    const storeId = container.querySelector("#store-select").value;
    const category = container.querySelector("#category-select").value;
    const startDate = container.querySelector("#start-date").value;
    const endDate = container.querySelector("#end-date").value;

    if (!storeId) {
      showError("店舗を選択してください");
      return false;
    }

    if (!category) {
      showError("商品カテゴリを選択してください");
      return false;
    }

    if (!startDate) {
      showError("予測期間の開始日を設定してください");
      return false;
    }

    if (!endDate) {
      showError("予測期間の終了日を設定してください");
      return false;
    }

    if (new Date(startDate) >= new Date(endDate)) {
      showError("開始日は終了日より前の日付を入力してください");
      return false;
    }

    if (new Date(startDate) < new Date()) {
      showError("開始日は現在日以降の日付を設定してください");
      return false;
    }

    const seasonal = container.querySelector("#seasonal-model").checked;
    const event = container.querySelector("#event-model").checked;
    const weather = container.querySelector("#weather-model").checked;

    if (!seasonal && !event && !weather) {
      showError("予測モデルを選択してください");
      return false;
    }

    return true;
  }

  // AI予測実行ボタン
  container.querySelector("#btn-predict").addEventListener("click", async () => {
    if (!validatePredictionForm()) return;

    showProcessing(true);

    // 予測処理のシミュレーション
    setTimeout(async () => {
      showProcessing(false);

      const storeId = container.querySelector("#store-select").value;
      const category = container.querySelector("#category-select").value;
      const startDate = container.querySelector("#start-date").value;
      const endDate = container.querySelector("#end-date").value;

      // 需要予測結果を保存
      const predictionData = {
        店舗ID: storeId,
        商品ID: "sample-product-id",
        予測対象日: startDate,
        予測数量: Math.floor(Math.random() * 200) + 50,
        予測精度: Math.floor(Math.random() * 30) + 70,
        推奨発注数量: Math.floor(Math.random() * 150) + 30,
        予測モデルバージョン: "v2.1.0",
        予測ステータス: "完了",
        発注済フラグ: false,
        備考: `カテゴリ: ${category}`,
        作成日時: new Date().toISOString(),
        更新日時: new Date().toISOString()
      };

      if (predictionTableIndex >= 0) {
        const saved = await window.aivicApi.save(predictionTableIndex, predictionData);
        if (saved) {
          const rows = await window.aivicApi.list(predictionTableIndex);
          if (rows) renderPredictionRows(rows);
        }
      }

      showPredictionResults();
    }, 2000);
  });

  // エクスポートボタン
  container.querySelector("#btn-export").addEventListener("click", async () => {
    if (predictionTableIndex >= 0) {
      const rows = await window.aivicApi.list(predictionTableIndex);
      if (rows) {
        const headers = ["商品コード", "商品名", "予測対象日", "予測数量", "予測精度", "推奨発注数量", "予測ステータス"];
        const csvContent = "\uFEFF" + headers.join(",") + "\n" + 
          rows.map(r => [
            r.商品コード || "",
            r.商品名 || "",
            r.予測対象日 || "",
            r.予測数量 || "",
            r.予測精度 || "",
            r.推奨発注数量 || "",
            r.予測ステータス || ""
          ].join(",")).join("\n");

        const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
        const link = document.createElement("a");
        link.href = URL.createObjectURL(blob);
        link.download = "demand_prediction_results.csv";
        link.click();
      }
    }
  });

  // 行レベル操作（削除・詳細）
  container.addEventListener("click", async (e) => {
    const deleteBtn = e.target.closest(".delete-btn");
    if (deleteBtn) {
      if (!confirm("この予測結果を削除しますか？")) return;

      if (predictionTableIndex >= 0) {
        await window.aivicApi.delete(predictionTableIndex, deleteBtn.dataset.id);
        const rows = await window.aivicApi.list(predictionTableIndex);
        if (rows) renderPredictionRows(rows);
      }
    }

    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      window.showScreen("scr-1778591885672"); // AI需要予測処理画面
    }
  });

  // 初期データ読み込み
  if (predictionTableIndex >= 0) {
    window.aivicApi.list(predictionTableIndex).then(rows => {
      if (rows) renderPredictionRows(rows);
    });
  }
}

function(container, apiUrl, tables) {
  let currentProducts = [];
  let currentStore = null;

  // 店舗データを読み込んでドロップダウンに設定
  function loadStores() {
    const storeSelect = container.querySelector('#store-select');
    const storeTable = tables.find(t => t.tableName === '店舗マスタ');
    if (storeTable && storeTable.records) {
      storeTable.records.forEach(store => {
        if (store.有効フラグ) {
          const option = document.createElement('option');
          option.value = store.店舗ID;
          option.textContent = `${store.店舗コード} - ${store.店舗名}`;
          storeSelect.appendChild(option);
        }
      });
    }
  }

  // 商品テーブル再描画
  function renderProducts(products) {
    const tbody = container.querySelector('#product-tbody');
    const tableWrap = container.querySelector('#product-table-wrap');
    const noResults = container.querySelector('#no-results-message');
    const noStore = container.querySelector('#no-store-message');
    const bulkOrderBtn = container.querySelector('#btn-bulk-order');

    if (!currentStore) {
      tableWrap.style.display = 'none';
      noResults.style.display = 'none';
      noStore.style.display = 'block';
      bulkOrderBtn.style.display = 'none';
      return;
    }

    noStore.style.display = 'none';

    if (!products || products.length === 0) {
      tableWrap.style.display = 'none';
      noResults.style.display = 'block';
      bulkOrderBtn.style.display = 'none';
      return;
    }

    noResults.style.display = 'none';
    tableWrap.style.display = 'block';
    bulkOrderBtn.style.display = 'inline-block';

    tbody.innerHTML = products.map(product => {
      const prediction = getPredictionForProduct(product.商品ID);
      const stock = Math.floor(Math.random() * 100) + 10; // 模擬在庫数
      const recommended = Math.max(0, prediction - stock);

      return `
        <tr data-id="${product.商品ID}">
          <td>${product.商品コード || ''}</td>
          <td>${product.商品名 || ''}</td>
          <td>${getCategoryName(product.商品カテゴリID) || ''}</td>
          <td style="text-align: right;">${prediction}</td>
          <td style="text-align: right;">${stock}</td>
          <td style="text-align: right; color: var(--primary); font-weight: bold;">${recommended}</td>
          <td>
            <input type="number" class="input order-quantity" data-product-id="${product.商品ID}" 
                   min="0" max="9999" style="width: 80px;" value="${recommended}">
          </td>
          <td>
            <input type="text" class="input order-reason" data-product-id="${product.商品ID}" 
                   placeholder="発注理由" style="width: 150px;">
          </td>
          <td>
            <button class="action-btn secondary order-btn" data-product-id="${product.商品ID}">発注</button>
            <button class="action-btn secondary adjust-btn" data-product-id="${product.商品ID}">調整</button>
          </td>
        </tr>
      `;
    }).join('');

    updatePredictionSummary(products);
  }

  // 需要予測データを取得（模擬データ）
  function getPredictionForProduct(productId) {
    return Math.floor(Math.random() * 50) + 20;
  }

  // カテゴリ名を取得
  function getCategoryName(categoryId) {
    const categories = ['食品', '日用品', '衣料品', '家電'];
    return categories[Math.floor(Math.random() * categories.length)];
  }

  // 予測サマリー更新
  function updatePredictionSummary(products) {
    const predictionArea = container.querySelector('#prediction-area');
    if (products && products.length > 0) {
      predictionArea.style.display = 'block';

      let totalPrediction = 0;
      let totalStock = 0;
      let totalRecommended = 0;

      products.forEach(product => {
        const prediction = getPredictionForProduct(product.商品ID);
        const stock = Math.floor(Math.random() * 100) + 10;
        const recommended = Math.max(0, prediction - stock);

        totalPrediction += prediction;
        totalStock += stock;
        totalRecommended += recommended;
      });

      container.querySelector('#total-prediction').textContent = totalPrediction;
      container.querySelector('#total-stock').textContent = totalStock;
      container.querySelector('#total-recommended').textContent = totalRecommended;
    } else {
      predictionArea.style.display = 'none';
    }
  }

  // 商品データをフィルタリング
  function filterProducts() {
    const productTable = tables.find(t => t.tableName === '商品マスタ');
    if (!productTable || !productTable.records) return [];

    let filtered = productTable.records.filter(p => p.有効フラグ);

    // カテゴリフィルタ
    const category = container.querySelector('#category-select').value;
    if (category) {
      filtered = filtered.filter(p => getCategoryName(p.商品カテゴリID) === category);
    }

    // 商品名検索
    const searchText = container.querySelector('#search-product').value.toLowerCase();
    if (searchText) {
      filtered = filtered.filter(p => 
        (p.商品名 || '').toLowerCase().includes(searchText) ||
        (p.商品コード || '').toLowerCase().includes(searchText)
      );
    }

    return filtered;
  }

  // 発注処理
  async function processOrder(productId, quantity, reason) {
    const productTable = tables.find(t => t.tableName === '商品マスタ');
    const product = productTable.records.find(p => p.商品ID === productId);

    if (!product) {
      alert('商品が見つかりません');
      return false;
    }

    // バリデーション
    if (!quantity || quantity <= 0) {
      alert('発注量は正の数値を入力してください');
      return false;
    }

    if (isNaN(quantity)) {
      alert('発注量は数値で入力してください');
      return false;
    }

    // 発注データ作成
    const orderData = {
      店舗ID: currentStore,
      商品ID: productId,
      発注日: new Date().toISOString(),
      納期予定日: new Date(Date.now() + product.リードタイム日数 * 24 * 60 * 60 * 1000).toISOString(),
      発注数量: parseInt(quantity),
      予測数量: getPredictionForProduct(productId),
      発注単価: product.単価 || 0,
      発注金額: parseInt(quantity) * (product.単価 || 0),
      発注方法: reason ? 'AI推奨修正' : 'AI推奨採用',
      発注ステータス: '発注済',
      仕入先ID: product.仕入先ID,
      発注理由: reason || 'AI需要予測に基づく自動発注',
      自動発注フラグ: !reason,
      作成者ID: 'current-user-id',
      更新者ID: 'current-user-id'
    };

    const orderTableIndex = tables.findIndex(t => t.tableName === '発注データ');
    const saved = await window.aivicApi.save(orderTableIndex, orderData);

    if (saved) {
      alert('発注が完了しました');
      return true;
    } else {
      alert('発注処理でエラーが発生しました');
      return false;
    }
  }

  // CSVエクスポート
  function exportCSV() {
    if (!currentProducts || currentProducts.length === 0) {
      alert('エクスポートするデータがありません');
      return;
    }

    const headers = ['商品コード', '商品名', 'カテゴリ', '予測需要量', '現在在庫数', '推奨発注量'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...currentProducts.map(product => {
        const prediction = getPredictionForProduct(product.商品ID);
        const stock = Math.floor(Math.random() * 100) + 10;
        const recommended = Math.max(0, prediction - stock);

        return [
          `"${product.商品コード || ''}"`,
          `"${product.商品名|| ''}"`,
          `"${getCategoryName(product.商品カテゴリID) || ''}"`,
          prediction,
          stock,
          recommended
        ].join(',');
      })
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `発注管理_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 初期化
  loadStores();
  renderProducts([]);

  // イベントリスナー
  container.querySelector('#store-select').addEventListener('change', (e) => {
    currentStore = e.target.value;
    if (currentStore) {
      currentProducts = filterProducts();
      renderProducts(currentProducts);
    } else {
      currentProducts = [];
      renderProducts([]);
    }
  });

  container.querySelector('#btn-search').addEventListener('click', () => {
    if (!currentStore) {
      alert('店舗を選択してください');
      return;
    }

    // 日付バリデーション
    const startDate = container.querySelector('#date-start').value;
    const endDate = container.querySelector('#date-end').value;

    if (startDate && endDate && startDate > endDate) {
      alert('終了日は開始日以降の日付を入力してください');
      return;
    }

    currentProducts = filterProducts();
    renderProducts(currentProducts);
  });

  container.querySelector('#btn-reset').addEventListener('click', () => {
    container.querySelector('#category-select').value = '';
    container.querySelector('#search-product').value = '';
    container.querySelector('#date-start').value = '';
    container.querySelector('#date-end').value = '';

    if (currentStore) {
      currentProducts = filterProducts();
      renderProducts(currentProducts);
    }
  });

  container.querySelector('#btn-export').addEventListener('click', exportCSV);

  // 商品テーブルのイベントデリゲーション
  container.addEventListener('click', async (e) => {
    const orderBtn = e.target.closest('.order-btn');
    const adjustBtn = e.target.closest('.adjust-btn');

    if (orderBtn) {
      const productId = orderBtn.dataset.productId;
      const quantityInput = container.querySelector(`.order-quantity[data-product-id="${productId}"]`);
      const reasonInput = container.querySelector(`.order-reason[data-product-id="${productId}"]`);

      const quantity = quantityInput.value;
      const reason = reasonInput.value;

      if (await processOrder(productId, quantity, reason)) {
        quantityInput.value = '';
        reasonInput.value = '';
      }
    }

    if (adjustBtn) {
      const productId = adjustBtn.dataset.productId;
      const quantityInput = container.querySelector(`.order-quantity[data-product-id="${productId}"]`);
      const currentValue = parseInt(quantityInput.value) || 0;

      const newValue = prompt('発注量を入力してください:', currentValue);
      if (newValue !== null && !isNaN(newValue) && newValue >= 0) {
        quantityInput.value = newValue;
      }
    }
  });

  // 一括発注
  container.querySelector('#btn-bulk-order').addEventListener('click', async () => {
    const quantities = container.querySelectorAll('.order-quantity');
    const reasons = container.querySelectorAll('.order-reason');

    let orderCount = 0;
    for (let i = 0; i < quantities.length; i++) {
      const quantity = quantities[i].value;
      if (quantity && parseInt(quantity) > 0) {
        const productId = quantities[i].dataset.productId;
        const reason = reasons[i].value;

        if (await processOrder(productId, quantity, reason)) {
          orderCount++;
          quantities[i].value = '';
          reasons[i].value = '';
        }
      }
    }

    if (orderCount > 0) {
      alert(`${orderCount}件の発注が完了しました`);
    } else {
      alert('発注する商品がありません');
    }
  });
}

function(container, apiUrl, tables) {
  let autoRefreshInterval = null;
  let currentLogId = null;

  // テーブル再描画関数
  function renderRows(rows) {
    const tbody = container.querySelector("#log-table-body");
    tbody.innerHTML = rows.map(row => {
      const statusClass = getStatusClass(row.処理ステータス || '');
      const startTime = formatDateTime(row.収集開始日時);
      const processingTime = row.処理時間秒 ? `${row.処理時間秒}秒` : '-';
      const qualityScore = row.データ品質スコア || '-';

      return `
        <tr data-id="${row.id}">
          <td>${startTime}</td>
          <td>${row.データ種別 || '-'}</td>
          <td>${row.データソース || '-'}</td>
          <td>${row.店舗ID || '-'}</td>
          <td><span class="status-badge ${statusClass}">${row.処理ステータス || '-'}</span></td>
          <td>${row.収集件数 || 0}</td>
          <td>${row.エラー件数 || 0}</td>
          <td>${processingTime}</td>
          <td>${qualityScore}</td>
          <td>
            <button class="action-btn secondary detail-btn" data-id="${row.id}">詳細</button>
            ${row.処理ステータス === '失敗' ? `<button class="action-btn secondary retry-btn" data-id="${row.id}">再実行</button>` : ''}
          </td>
        </tr>
      `;
    }).join("");

    updateSummary(rows);
  }

  // ステータスクラス取得
  function getStatusClass(status) {
    switch(status) {
      case '成功': return 'status-success';
      case '失敗': return 'status-error';
      case '実行中': return 'status-running';
      case '警告': return 'status-warning';
      default: return '';
    }
  }

  // 日時フォーマット
  function formatDateTime(dateStr) {
    if (!dateStr) return '-';
    const date = new Date(dateStr);
    return date.toLocaleString('ja-JP', {
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit'
    });
  }

  // サマリー更新
  function updateSummary(rows) {
    const totalCount = rows.length;
    const successCount = rows.filter(r => r.処理ステータス === '成功').length;
    const errorCount = rows.filter(r => r.処理ステータス === '失敗').length;
    const lastExecution = rows.length > 0 ? 
      formatDateTime(Math.max(...rows.map(r => new Date(r.収集開始日時 || 0)))) : '-';

    container.querySelector("#total-count").textContent = totalCount;
    container.querySelector("#success-count").textContent = successCount;
    container.querySelector("#error-count").textContent = errorCount;
    container.querySelector("#last-execution").textContent = lastExecution;

    // エラーインジケーター表示制御
    const errorIndicator = container.querySelector("#error-indicator");
    if (errorCount > 0) {
      errorIndicator.classList.remove('hidden');
    } else {
      errorIndicator.classList.add('hidden');
    }
  }

  // 初期データ描画
  renderRows(tables[13].records || []);

  // 検索・絞り込み
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const dataSource = container.querySelector("#filter-data-source").value;
    const logLevel = container.querySelector("#filter-log-level").value;
    const startDate = container.querySelector("#filter-start-date").value;
    const endDate = container.querySelector("#filter-end-date").value;

    // 日付バリデーション
    if (startDate && endDate && new Date(startDate) > new Date(endDate)) {
      alert("開始日は終了日より前の日付を設定してください");
      return;
    }

    try {
      const rows = await window.aivicApi.list(13);
      if (!rows) return;

      const filtered = rows.filter(row => {
        if (dataSource && row.データソース !== dataSource) return false;
        if (logLevel && row.処理ステータス !== logLevel) return false;
        if (startDate && new Date(row.収集開始日時) < new Date(startDate)) return false;
        if (endDate && new Date(row.収集開始日時) > new Date(endDate)) return false;
        return true;
      });

      renderRows(filtered);
    } catch (error) {
      console.error('検索エラー:', error);
    }
  });

  // ログエクスポート
  container.querySelector("#btn-export").addEventListener("click", async () => {
    try {
      const rows = await window.aivicApi.list(13);
      if (!rows) {
        alert("ログエクスポートに失敗しました");
        return;
      }

      const headers = ['収集日時', 'データ種別', 'データソース', '店舗ID', 'ステータス', '収集件数', 'エラー件数', '処理時間', '品質スコア'];
      const csvContent = [
        headers.join(','),
        ...rows.map(row => [
          formatDateTime(row.収集開始日時),
          row.データ種別 || '',
          row.データソース || '',
          row.店舗ID || '',
          row.処理ステータス || '',
          row.収集件数 || 0,
          row.エラー件数 || 0,
          row.処理時間秒 || 0,
          row.データ品質スコア || 0
        ].map(field => `"${field}"`).join(','))
      ].join('\n');

      const blob = new Blob(['\uFEFF' + csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `data_collection_logs_${new Date().toISOString().slice(0, 10)}.csv`;
      link.click();
    } catch (error) {
      alert("ログエクスポートに失敗しました");
      console.error('エクスポートエラー:', error);
    }
  });

  // エラーログ一括再実行
  container.querySelector("#btn-retry-errors").addEventListener("click", async () => {
    if (!confirm("エラーログを一括で再実行しますか？")) return;

    try {
      const rows = await window.aivicApi.list(13);
      if (!rows) return;

      const errorLogs = rows.filter(r => r.処理ステータス === '失敗');
      if (errorLogs.length === 0) {
        alert("再実行対象のエラーログがありません");
        return;
      }

      for (const log of errorLogs) {
        await window.aivicApi.update(13, log.id, {
          処理ステータス: '実行中',
          再実行フラグ: true,
          更新日時: new Date().toISOString()
        });
      }

      alert(`${errorLogs.length}件のエラーログの再実行を開始しました`);

      // 再描画
      const updatedRows = await window.aivicApi.list(13);
      if (updatedRows) renderRows(updatedRows);
    } catch (error) {
      alert("エラーログ再実行が失敗しました");
      console.error('再実行エラー:', error);
    }
  });

  // 自動更新トグル
  container.querySelector("#btn-auto-refresh-toggle").addEventListener("click", () => {
    const statusSpan = container.querySelector("#auto-refresh-status");

    if (autoRefreshInterval) {
      clearInterval(autoRefreshInterval);
      autoRefreshInterval = null;
      statusSpan.textContent = "自動更新: OFF";
    } else {
      autoRefreshInterval = setInterval(async () => {
        const rows = await window.aivicApi.list(13);
        if (rows) renderRows(rows);
      }, 30000); // 30秒間隔
      statusSpan.textContent = "自動更新: ON";
    }
  });

  // アラート通知設定
  container.querySelector("#btn-alert-settings").addEventListener("click", () => {
    container.querySelector("#alert-settings-modal").classList.remove('hidden');
  });

  // モーダル関連イベント
  container.querySelector("#modal-close").addEventListener("click", () => {
    container.querySelector("#log-detail-modal").classList.add('hidden');
  });

  container.querySelector("#btn-close-modal").addEventListener("click", () => {
    container.querySelector("#log-detail-modal").classList.add('hidden');
  });

  container.querySelector("#alert-modal-close").addEventListener("click", () => {
    container.querySelector("#alert-settings-modal").classList.add('hidden');
  });

  container.querySelector("#btn-cancel-alert-settings").addEventListener("click", () => {
    container.querySelector("#alert-settings-modal").classList.add('hidden');
  });

  container.querySelector("#btn-save-alert-settings").addEventListener("click", () => {
    alert("アラート通知設定を保存しました");
    container.querySelector("#alert-settings-modal").classList.add('hidden');
  });

  // 行レベル操作（イベントデリゲーション）
  container.addEventListener("click", async (e) => {
    // 詳細表示
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      const logId = detailBtn.dataset.id;
      const rows = await window.aivicApi.list(13);
      if (!rows) return;

      const log = rows.find(r => r.id === logId);
      if (!log) return;

      // 詳細モーダルに情報設定
      container.querySelector("#detail-log-id").textContent = log.id || '-';
      container.querySelector("#detail-data-type").textContent = log.データ種別 || '-';
      container.querySelector("#detail-data-source").textContent = log.データソース || '-';
      container.querySelector("#detail-start-time").textContent = formatDateTime(log.収集開始日時);
      container.querySelector("#detail-end-time").textContent = formatDateTime(log.収集終了日時);
      container.querySelector("#detail-status").textContent = log.処理ステータス || '-';
      container.querySelector("#detail-success-count").textContent = log.収集件数 || 0;
      container.querySelector("#detail-error-count").textContent = log.エラー件数 || 0;
      container.querySelector("#detail-processing-time").textContent = log.処理時間秒 ? `${log.処理時間秒}秒` : '-';
      container.querySelector("#detail-quality-score").textContent = log.データ品質スコア || '-';
      container.querySelector("#detail-error-message").textContent = log.エラーメッセージ || '-';
      container.querySelector("#detail-remarks").textContent = log.備考 || '-';

      currentLogId = logId;
      container.querySelector("#log-detail-modal").classList.remove('hidden');
    }

    // 単一再実行
    const retryBtn = e.target.closest(".retry-btn");
    if (retryBtn) {
      const logId = retryBtn.dataset.id;
      if (!confirm("このログを再実行しますか？")) return;

      try {
        const updated = await window.aivicApi.update(13, logId, {
          処理ステータス: '実行中',
          再実行フラグ: true,
          更新日時: new Date().toISOString()
        });

        if (updated) {
          alert("ログの再実行を開始しました");
          const rows = await window.aivicApi.list(13);
          if (rows) renderRows(rows);
        } else {
          alert("エラーログ再実行が失敗しました");
        }
      } catch (error) {
        alert("エラーログ再実行が失敗しました");
        console.error('再実行エラー:', error);
      }
    }
  });

  // 単一ログ再実行（モーダル内）
  container.querySelector("#btn-retry-single").addEventListener("click", async () => {
    if (!currentLogId) return;
    if (!confirm("このログを再実行しますか？")) return;

    try {
      const updated = await window.aivicApi.update(13, currentLogId, {
        処理ステータス: '実行中',
        再実行フラグ: true,
        更新日時: new Date().toISOString()
      });

      if (updated) {
        alert("ログの再実行を開始しました");
        container.querySelector("#log-detail-modal").classList.add('hidden');
        const rows = await window.aivicApi.list(13);
        if (rows) renderRows(rows);
      } else {
        alert("エラーログ再実行が失敗しました");
      }
    } catch (error) {
      alert("エラーログ再実行が失敗しました");
      console.error('再実行エラー:', error);
    }
  });

  // モーダル外クリックで閉じる
  container.addEventListener("click", (e) => {
    if (e.target.classList.contains('modal')) {
      e.target.classList.add('hidden');
    }
  });
}

function(container, apiUrl, tables) {
  let currentPage = 1;
  const itemsPerPage = 20;
  let allHistoryData = [];
  let filteredData = [];
  let userList = [];

  // ユーザー一覧を取得してセレクトボックスに設定
  async function loadUsers() {
    try {
      const users = await window.aivicApi.list(0); // ログインユーザーテーブル
      if (users) {
        userList = users;
        const userSelect = container.querySelector("#filter-user");
        userSelect.innerHTML = '<option value="">全ユーザー</option>';
        users.forEach(user => {
          userSelect.innerHTML += `<option value="${user.ユーザーID}">${user.ユーザー名}</option>`;
        });
      }
    } catch (error) {
      console.error("ユーザー一覧の取得に失敗しました:", error);
    }
  }

  // 操作履歴テーブルの再描画
  function renderRows(rows) {
    const tbody = container.querySelector("#history-tbody");
    const noResults = container.querySelector("#no-results");

    if (!rows || rows.length === 0) {
      tbody.innerHTML = "";
      noResults.classList.remove("hidden");
      updatePagination(0);
      return;
    }

    noResults.classList.add("hidden");

    // ページネーション用のデータスライス
    const startIndex = (currentPage - 1) * itemsPerPage;
    const endIndex = startIndex + itemsPerPage;
    const pageData = rows.slice(startIndex, endIndex);

    tbody.innerHTML = pageData.map(row => {
      const userName = getUserName(row.ユーザーID);
      const operationDate = row.操作日時 ? new Date(row.操作日時).toLocaleString('ja-JP') : '';
      const resultBadge = getResultBadge(row.処理結果);

      return `
        <tr data-id="${row.操作履歴ID}">
          <td>${operationDate}</td>
          <td>${userName}</td>
          <td>${row.操作種別 || ''}</td>
          <td>${row.操作画面 || ''}</td>
          <td>${row.IPアドレス || ''}</td>
          <td>${resultBadge}</td>
          <td>${row.処理時間 || ''}</td>
          <td>
            <button class="action-btn secondary detail-btn" data-id="${row.操作履歴ID}">詳細</button>
          </td>
        </tr>
      `;
    }).join("");

    updatePagination(rows.length);
  }

  // ユーザー名を取得
  function getUserName(userId) {
    const user = userList.find(u => u.ユーザーID === userId);
    return user ? user.ユーザー名 : userId || '';
  }

  // 処理結果のバッジを生成
  function getResultBadge(result) {
    if (!result) return '';

    let color = '';
    switch (result) {
      case '成功':
        color = 'background: #22c55e; color: white;';
        break;
      case '失敗':
        color = 'background: #ef4444; color: white;';
        break;
      case 'エラー':
        color = 'background: #f59e0b; color: white;';
        break;
      default:
        color = 'background: var(--bg-main); color: var(--text);';
    }

    return `<span style="padding: 4px 8px; border-radius: 4px; font-size: 12px; ${color}">${result}</span>`;
  }

  // ページネーション更新
  function updatePagination(totalItems) {
    const totalPages = Math.ceil(totalItems / itemsPerPage);
    const pageInfo = container.querySelector("#page-info");
    const prevBtn = container.querySelector("#btn-prev");
    const nextBtn = container.querySelector("#btn-next");

    pageInfo.textContent = `${currentPage} / ${totalPages || 1}`;
    prevBtn.disabled = currentPage <= 1;
    nextBtn.disabled = currentPage >= totalPages;

    if (totalPages <= 1) {
      container.querySelector("#pagination").style.display = "none";
    } else {
      container.querySelector("#pagination").style.display = "flex";
    }
  }

  // フィルタリング処理
  function applyFilters() {
    const startDate = container.querySelector("#filter-start-date").value;
    const endDate = container.querySelector("#filter-end-date").value;
    const userId = container.querySelector("#filter-user").value;
    const operationType = container.querySelector("#filter-operation-type").value;
    const screenName = container.querySelector("#filter-screen-name").value.toLowerCase();
    const ipAddress = container.querySelector("#filter-ip-address").value.toLowerCase();
    const result = container.querySelector("#filter-result").value;

    // 日付バリデーション
    if (startDate && endDate && new Date(startDate) > new Date(endDate)) {
      alert("開始日が終了日より後の日付になっています。正しい日付範囲を入力してください。");
      return;
    }

    // IPアドレスバリデーション
    if (ipAddress && !isValidIPAddress(ipAddress)) {
      alert("不正なIPアドレス形式です。正しい形式で入力してください。");
      return;
    }

    filteredData = allHistoryData.filter(row => {
      // 日付範囲フィルター
      if (startDate || endDate) {
        const rowDate = new Date(row.操作日時);
        if (startDate && rowDate < new Date(startDate)) return false;
        if (endDate && rowDate > new Date(endDate + 'T23:59:59')) return false;
      }

      // ユーザーフィルター
      if (userId && row.ユーザーID !== userId) return false;

      // 操作種別フィルター
      if (operationType && row.操作種別 !== operationType) return false;

      // 画面名フィルター
      if (screenName && !row.操作画面?.toLowerCase().includes(screenName)) return false;

      // IPアドレスフィルター
      if (ipAddress && !row.IPアドレス?.toLowerCase().includes(ipAddress)) return false;

      // 処理結果フィルター
      if (result && row.処理結果 !== result) return false;

      return true;
    });

    currentPage = 1;
    renderRows(filteredData);
  }

  // IPアドレス形式チェック
  function isValidIPAddress(ip) {
    const ipRegex = /^(?:(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3}(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$/;
    return ipRegex.test(ip) || ip === ''; // 空文字は許可
  }

  // 検索条件クリア
  function clearFilters() {
    container.querySelector("#filter-start-date").value = '';
    container.querySelector("#filter-end-date").value = '';
    container.querySelector("#filter-user").value = '';
    container.querySelector("#filter-operation-type").value = '';
    container.querySelector("#filter-screen-name").value = '';
    container.querySelector("#filter-ip-address").value = '';
    container.querySelector("#filter-result").value = '';

    filteredData = [...allHistoryData];
    currentPage = 1;
    renderRows(filteredData);
  }

  // CSV出力
  async function exportCSV() {
    try {
      const data = filteredData.length > 0 ? filteredData : allHistoryData;

      if (data.length > 100000) {
        alert("データ量が多すぎます。検索条件を絞り込んでから出力してください。");
        return;
      }

      const headers = ['操作日時', 'ユーザー名', '操作種別', '操作画面', '操作対象テーブル', '操作対象ID', '操作内容', 'IPアドレス', 'ユーザーエージェント', '処理結果', 'エラーメッセージ', '処理時間'];

      const csvContent = [
        headers.join(','),
        ...data.map(row => [
          `"${row.操作日時 ? new Date(row.操作日時).toLocaleString('ja-JP') : ''}"`,
          `"${getUserName(row.ユーザーID)}"`,
          `"${row.操作種別 || ''}"`,
          `"${row.操作画面 || ''}"`,
          `"${row.操作対象テーブル || ''}"`,
          `"${row.操作対象ID || ''}"`,
          `"${(row.操作内容 || '').replace(/"/g, '""')}"`,
          `"${row.IPアドレス || ''}"`,
          `"${(row.ユーザーエージェント || '').replace(/"/g, '""')}"`,
          `"${row.処理結果 || ''}"`,
          `"${(row.エラーメッセージ || '').replace(/"/g, '""')}"`,
          `"${row.処理時間 || ''}"`
        ].join(','))
      ].join('\n');

      const bom = '\uFEFF';
      const blob = new Blob([bom + csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `システム操作履歴_${new Date().toISOString().slice(0, 10)}.csv`;
      link.click();
      URL.revokeObjectURL(link.href);
    } catch (error) {
      alert("CSV出力中にエラーが発生しました。");
      console.error("CSV export error:", error);
    }
  }

  // 詳細モーダル表示
  function showDetailModal(historyId) {
    const history = allHistoryData.find(h => h.操作履歴ID === historyId);
    if (!history) return;

    container.querySelector("#detail-datetime").textContent = history.操作日時 ? new Date(history.操作日時).toLocaleString('ja-JP') : '';
    container.querySelector("#detail-user").textContent = getUserName(history.ユーザーID);
    container.querySelector("#detail-operation").textContent = history.操作種別 || '';
    container.querySelector("#detail-screen").textContent = history.操作画面 || '';
    container.querySelector("#detail-target").textContent = `${history.操作対象テーブル || ''} ${history.操作対象ID || ''}`.trim();
    container.querySelector("#detail-ip").textContent = history.IPアドレス || '';
    container.querySelector("#detail-useragent").textContent = history.ユーザーエージェント || '';
    container.querySelector("#detail-result").textContent = history.処理結果 || '';
    container.querySelector("#detail-time").textContent = history.処理時間 ? `${history.処理時間}ms` : '';
    container.querySelector("#detail-content-text").textContent = history.操作内容 || '';
    container.querySelector("#detail-error").textContent = history.エラーメッセージ || '';

    container.querySelector("#detail-modal").classList.remove("hidden");
  }

  // 初期データ読み込み
  async function loadData() {
    try {
      const historyData = await window.aivicApi.list(13); // システム操作履歴テーブル
      if (historyData) {
        allHistoryData = historyData.sort((a, b) => new Date(b.操作日時) - new Date(a.操作日時));
        filteredData = [...allHistoryData];
        renderRows(filteredData);
      } else {
        allHistoryData = tables[13]?.records || [];
        filteredData = [...allHistoryData];
        renderRows(filteredData);
      }
    } catch (error) {
      console.error("データ読み込みエラー:", error);
      allHistoryData = tables[13]?.records || [];
      filteredData = [...allHistoryData];
      renderRows(filteredData);
    }
  }

  // イベントリスナー設定
  container.querySelector("#btn-search").addEventListener("click", applyFilters);
  container.querySelector("#btn-clear").addEventListener("click", clearFilters);
  container.querySelector("#btn-csv-export").addEventListener("click", exportCSV);

  // ページネーション
  container.querySelector("#btn-prev").addEventListener("click", () => {
    if (currentPage > 1) {
      currentPage--;
      renderRows(filteredData);
    }
  });

  container.querySelector("#btn-next").addEventListener("click", () => {
    const totalPages = Math.ceil(filteredData.length / itemsPerPage);
    if (currentPage < totalPages) {
      currentPage++;
      renderRows(filteredData);
    }
  });

  // モーダル関連
  container.addEventListener("click", (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      showDetailModal(detailBtn.dataset.id);
    }
  });

  container.querySelector("#btn-close-modal").addEventListener("click", () => {
    container.querySelector("#detail-modal").classList.add("hidden");
  });

  container.querySelector("#detail-modal").addEventListener("click", (e) => {
    if (e.target.id === "detail-modal") {
      container.querySelector("#detail-modal").classList.add("hidden");
    }
  });

  // 初期化
  loadUsers();
  loadData();
}

function(container, apiUrl, tables) {
  let isProcessing = false;
  let weatherDataImported = false;
  let eventDataImported = false;

  // 初期化処理
  async function initialize() {
    await loadStores();
    await loadCategories();
    setupEventListeners();
    setDefaultDates();
  }

  // 店舗データの読み込み
  async function loadStores() {
    const storeSelect = container.querySelector('#store-select');
    const stores = await window.aivicApi.list(1); // 店舗マスタ
    if (stores) {
      stores.filter(store => store.有効フラグ).forEach(store => {
        const option = document.createElement('option');
        option.value = store.店舗ID;
        option.textContent = `${store.店舗コード} - ${store.店舗名}`;
        storeSelect.appendChild(option);
      });
    }
  }

  // 商品カテゴリの読み込み
  async function loadCategories() {
    const categoryContainer = container.querySelector('#category-checkboxes');
    const products = await window.aivicApi.list(2); // 商品マスタ
    if (products) {
      const categories = [...new Set(products.filter(p => p.有効フラグ).map(p => p.商品カテゴリID))];
      categories.forEach(categoryId => {
        const label = document.createElement('label');
        label.style.display = 'block';
        label.style.marginBottom = '5px';
        label.innerHTML = `<input type="checkbox" class="category-checkbox" value="${categoryId}"> カテゴリ ${categoryId}`;
        categoryContainer.appendChild(label);
      });
    }
  }

  // デフォルト日付設定
  function setDefaultDates() {
    const today = new Date();
    const tomorrow = new Date(today);
    tomorrow.setDate(tomorrow.getDate() + 1);
    const nextWeek = new Date(today);
    nextWeek.setDate(nextWeek.getDate() + 7);
    const lastMonth = new Date(today);
    lastMonth.setMonth(lastMonth.getMonth() - 1);

    container.querySelector('#prediction-start-date').value = tomorrow.toISOString().split('T')[0];
    container.querySelector('#prediction-end-date').value = nextWeek.toISOString().split('T')[0];
    container.querySelector('#learning-start-date').value = lastMonth.toISOString().split('T')[0];
    container.querySelector('#learning-end-date').value = today.toISOString().split('T')[0];
  }

  // イベントリスナー設定
  function setupEventListeners() {
    // 全選択チェックボックス
    container.querySelector('#select-all-categories').addEventListener('change', function() {
      const checkboxes = container.querySelectorAll('.category-checkbox');
      checkboxes.forEach(cb => cb.checked = this.checked);
    });

    // 季節要因スライダー
    container.querySelector('#seasonal-factor').addEventListener('input', function() {
      container.querySelector('#seasonal-value').textContent = this.value + '%';
    });

    // 天候データ取込
    container.querySelector('#btn-weather-import').addEventListener('click', async function() {
      try {
        this.disabled = true;
        this.textContent = '取込中...';

        // 模擬的な天候データ取込処理
        await new Promise(resolve => setTimeout(resolve, 2000));

        weatherDataImported = true;
        container.querySelector('#weather-status').textContent = '取込完了';
        container.querySelector('#weather-status').style.color = 'var(--primary)';
        this.textContent = '再取込';
      } catch (error) {
        container.querySelector('#weather-status').textContent = '取込失敗';
        container.querySelector('#weather-status').style.color = '#ff4444';
        this.textContent = '天候データ取込';
        showError('天候データの取得に失敗しました。データソースの設定を確認してください。');
      } finally {
        this.disabled = false;
      }
    });

    // イベントデータ取込
    container.querySelector('#btn-event-import').addEventListener('click', async function() {
      try {
        this.disabled = true;
        this.textContent = '取込中...';

        // 模擬的なイベントデータ取込処理
        await new Promise(resolve => setTimeout(resolve, 1500));

        eventDataImported = true;
        container.querySelector('#event-status').textContent = '取込完了';
        container.querySelector('#event-status').style.color = 'var(--primary)';
        this.textContent = '再取込';
      } catch (error) {
        container.querySelector('#event-status').textContent = '取込失敗';
        container.querySelector('#event-status').style.color = '#ff4444';
        this.textContent = 'イベントデータ取込';
        showError('イベントデータの取込に失敗しました。ファイル形式を確認してください。');
      } finally {
        this.disabled = false;
      }
    });

    // AI予測実行
    container.querySelector('#btn-ai-prediction').addEventListener('click', async function() {
      if (isProcessing) return;

      if (!validateInputs()) return;

      try {
        isProcessing = true;
        await executePrediction();
      } catch (error) {
        showError('AI予測実行が失敗しました。設定を確認してください。');
      } finally {
        isProcessing = false;
      }
    });

    // 詳細結果表示
    container.querySelector('#btn-view-details').addEventListener('click', function() {
      window.showScreen('scr-1778591838939'); // 需要予測管理画面
    });

    // 結果エクスポート
    container.querySelector('#btn-export-results').addEventListener('click', function() {
      exportResults();
    });
  }

  // 入力値検証
  function validateInputs() {
    const predictionStart = container.querySelector('#prediction-start-date').value;
    const predictionEnd = container.querySelector('#prediction-end-date').value;
    const storeId = container.querySelector('#store-select').value;
    const selectedCategories = container.querySelectorAll('.category-checkbox:checked');
    const selectedModel = container.querySelector('input[name="prediction-model"]:checked');
    const learningStart = container.querySelector('#learning-start-date').value;
    const learningEnd = container.querySelector('#learning-end-date').value;

    if (!predictionStart || !predictionEnd) {
      showError('予測期間の開始日と終了日を入力してください。');
      return false;
    }

    if (!storeId) {
      showError('店舗を選択してください。');
      return false;
    }

    if (selectedCategories.length === 0) {
      showError('商品カテゴリを選択してください。');
      return false;
    }

    if (!selectedModel) {
      showError('予測モデルを選択してください。');
      return false;
    }

    if (!learningStart || !learningEnd) {
      showError('学習データ期間の開始日と終了日を入力してください。');
      return false;
    }

    // 日付検証
    const today = new Date();
    const predStartDate = new Date(predictionStart);
    const predEndDate = new Date(predictionEnd);
    const learnStartDate = new Date(learningStart);
    const learnEndDate = new Date(learningEnd);

    if (predStartDate < today) {
      showError('予測期間に過去の日付は指定できません。');
      return false;
    }

    const oneYear = 365 * 24 * 60 * 60 * 1000;
    if (predEndDate - predStartDate > oneYear) {
      showError('予測期間は1年以内で設定してください。');
      return false;
    }

    if (learnEndDate - learnStartDate < predEndDate - predStartDate) {
      showError('学習データ期間は予測期間以上に設定してください。');
      return false;
    }

    return true;
  }

  // AI予測実行処理
  async function executePrediction() {
    hideError();
    showProgress();

    const steps = [
      { message: 'データを準備しています...', duration: 1000 },
      { message: '学習データを読み込んでいます...', duration: 2000 },
      { message: 'AIモデルを初期化しています...', duration: 1500 },
      { message: '外部要因データを分析しています...', duration: 2000 },
      { message: '需要予測を実行しています...', duration: 3000 },
      { message: '予測結果を生成しています...', duration: 1000 }
    ];

    let totalProgress = 0;
    const stepProgress = 100 / steps.length;

    for (let i = 0; i < steps.length; i++) {
      const step = steps[i];
      updateProgress(totalProgress, step.message);

      await new Promise(resolve => setTimeout(resolve, step.duration));

      totalProgress += stepProgress;
      updateProgress(Math.min(totalProgress, 100), step.message);
    }

    // 予測結果を保存
    const predictionData = {
      店舗ID: container.querySelector('#store-select').value,
      商品ID: 'sample-product-id',
      予測対象日: container.querySelector('#prediction-start-date').value,
      予測数量: Math.floor(Math.random() * 100) + 50,
      予測精度: Math.floor(Math.random() * 30) + 70,
      推奨発注数量: Math.floor(Math.random() * 80) + 40,
      予測モデルバージョン: container.querySelector('input[name="prediction-model"]:checked').value,
      予測ステータス: '完了',
      発注済フラグ: false,
      備考: 'AI予測処理により自動生成'
    };

    const saved = await window.aivicApi.save(10, predictionData); // 需要予測結果テーブル

    hideProgress();
    showResults(predictionData);
  }

  // 進捗表示
  function showProgress() {
    container.querySelector('#progress-panel').classList.remove('hidden');
    container.querySelector('#result-panel').classList.add('hidden');
    container.querySelector('#btn-ai-prediction').disabled = true;
    container.querySelector('#btn-ai-prediction').textContent = '処理中...';
  }

  // 進捗更新
  function updateProgress(percent, message) {
    container.querySelector('#progress-bar').style.width = percent + '%';
    container.querySelector('#progress-percent').textContent = Math.round(percent) + '%';
    container.querySelector('#progress-message').textContent = message;
  }

  // 進捗非表示
  function hideProgress() {
    container.querySelector('#progress-panel').classList.add('hidden');
    container.querySelector('#btn-ai-prediction').disabled = false;
    container.querySelector('#btn-ai-prediction').textContent = 'AI予測実行';
  }

  // 結果表示
  function showResults(data) {
    const resultsContainer = container.querySelector('#prediction-results');
    resultsContainer.innerHTML = `
      <div style="display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 20px;">
        <div style="text-align: center; padding: 20px; background: var(--bg-main); border-radius: 8px;">
          <div style="font-size: 24px; font-weight: bold; color: var(--primary);">${data.予測数量}</div>
          <div class="muted">予測需要数量</div>
        </div>
        <div style="text-align: center; padding: 20px; background: var(--bg-main); border-radius: 8px;">
          <div style="font-size: 24px; font-weight: bold; color: var(--primary);">${data.予測精度}%</div>
          <div class="muted">予測精度</div>
        </div>
        <div style="text-align: center; padding: 20px; background: var(--bg-main); border-radius: 8px;">
          <div style="font-size: 24px; font-weight: bold; color: var(--primary);">${data.推奨発注数量}</div>
          <div class="muted">推奨発注数量</div>
        </div>
      </div>
      <div style="margin-top: 20px;">
        <p><strong>使用モデル:</strong> ${data.予測モデルバージョン}</p>
        <p><strong>処理日時:</strong> ${new Date().toLocaleString()}</p>
        <p><strong>ステータス:</strong> ${data.予測ステータス}</p>
      </div>
    `;

    container.querySelector('#result-panel').classList.remove('hidden');
  }

  // エラー表示
  function showError(message) {
    container.querySelector('#error-message').textContent = message;
    container.querySelector('#error-panel').classList.remove('hidden');
  }

  // エラー非表示
  function hideError() {
    container.querySelector('#error-panel').classList.add('hidden');
  }

  // 結果エクスポート
  function exportResults() {
    const results = container.querySelector('#prediction-results');
    if (!results.innerHTML.trim()) return;

    const csvContent = '\uFEFF予測需要数量,予測精度,推奨発注数量,使用モデル,処理日時\n' +
                      `${container.querySelector('#prediction-results').textContent.match(/\d+/g).join(',')},${container.querySelector('input[name="prediction-model"]:checked').value},${new Date().toLocaleString()}`;

    const blob = new Blob([csvContent], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `prediction_results_${new Date().toISOString().split('T')[0]}.csv`;
    a.click();
    URL.revokeObjectURL(url);
  }

  // 初期化実行
  initialize();
}

function(container, apiUrl, tables) {
  let selectedProductId = null;
  let currentPrediction = null;

  // 店舗データを取得してドロップダウンに設定
  function loadStores() {
    window.aivicApi.list(1).then(stores => {
      const storeSelect = container.querySelector('#store-select');
      storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';
      if (stores) {
        stores.filter(s => s.有効フラグ).forEach(store => {
          storeSelect.innerHTML += `<option value="${store.id}">${store.店舗名}</option>`;
        });
      }
    });
  }

  // 商品データを取得してテーブルに表示
  function renderProducts(products) {
    const tbody = container.querySelector('#product-tbody');
    if (!products || products.length === 0) {
      tbody.innerHTML = '<tr><td colspan="6" class="muted" style="text-align:center;">商品が見つかりません</td></tr>';
      return;
    }

    tbody.innerHTML = products.map(product => `
      <tr data-id="${product.id}">
        <td><input type="radio" name="product-select" value="${product.id}" class="product-radio"></td>
        <td>${product.商品コード || ''}</td>
        <td>${product.商品名|| ''}</td>
        <td>${product.商品カテゴリID || ''}</td>
        <td>¥${(product.単価 || 0).toLocaleString()}</td>
        <td>${product.発注単位 || 1}</td>
      </tr>
    `).join('');
  }

  // 商品検索・絞り込み
  function filterProducts() {
    const storeId = container.querySelector('#store-select').value;
    const categoryId = container.querySelector('#category-select').value;
    const searchKeyword = container.querySelector('#product-search').value.toLowerCase();

    if (!storeId) {
      showError('store-error', '店舗を選択してください');
      return;
    }

    window.aivicApi.list(2).then(products => {
      if (!products) return;

      let filtered = products.filter(p => p.有効フラグ);

      if (categoryId) {
        filtered = filtered.filter(p => p.商品カテゴリID === categoryId);
      }

      if (searchKeyword) {
        filtered = filtered.filter(p => 
          (p.商品名 || '').toLowerCase().includes(searchKeyword) ||
          (p.商品コード || '').toLowerCase().includes(searchKeyword)
        );
      }

      renderProducts(filtered);
      clearError('store-error');
    });
  }

  // AI予測実行
  function executeAIPrediction() {
    const storeId = container.querySelector('#store-select').value;
    const periodStart = container.querySelector('#period-start').value;
    const periodEnd = container.querySelector('#period-end').value;

    // バリデーション
    if (!storeId) {
      showError('store-error', '店舗を選択してください');
      return;
    }
    if (!periodStart) {
      showError('period-start-error', '対象期間開始日を設定してください');
      return;
    }
    if (!periodEnd) {
      showError('period-end-error', '対象期間終了日を設定してください');
      return;
    }
    if (!selectedProductId) {
      alert('商品を選択してください');
      return;
    }

    clearAllErrors();

    // 予測結果を取得（模擬データ）
    window.aivicApi.list(8).then(predictions => {
      if (predictions) {
        const prediction = predictions.find(p => 
          p.店舗ID === storeId && p.商品ID === selectedProductId
        );

        if (prediction) {
          currentPrediction = prediction;
          displayPredictionResults(prediction);
        } else {
          // 模擬予測データを生成
          const mockPrediction = {
            予測数量: Math.floor(Math.random() * 100) + 50,
            予測精度: Math.floor(Math.random() * 30) + 70,
            推奨発注数量: Math.floor(Math.random() * 80) + 40
          };
          currentPrediction = mockPrediction;
          displayPredictionResults(mockPrediction);
        }
      }
    });
  }

  // 予測結果表示
  function displayPredictionResults(prediction) {
    container.querySelector('.prediction-placeholder').classList.add('hidden');
    container.querySelector('#prediction-results').classList.remove('hidden');

    container.querySelector('#predicted-quantity').textContent = `${prediction.予測数量 || 0}個`;
    container.querySelector('#prediction-accuracy').textContent = `${prediction.予測精度 || 0}%`;
    container.querySelector('#recommended-quantity').textContent = `${prediction.推奨発注数量 || 0}個`;
    container.querySelector('#ai-recommended').textContent = `${prediction.推奨発注数量 || 0}個`;
    container.querySelector('#manual-adjustment').placeholder = `${prediction.推奨発注数量 || 0}`;
  }

  // 発注量計算実行
  function calculateOrderQuantity() {
    const currentStock = parseInt(container.querySelector('#current-stock').value) || 0;
    const safetyStock = parseInt(container.querySelector('#safety-stock').value) || 0;
    const leadTime = parseInt(container.querySelector('#lead-time').value) || 0;
    const weatherImpact = parseInt(container.querySelector('#weather-impact').value) || 100;
    const eventImpact = parseInt(container.querySelector('#event-impact').value) || 100;
    const seasonalFactor = parseFloat(container.querySelector('#seasonal-factor').value) || 1.0;
    const manualAdjustment = parseInt(container.querySelector('#manual-adjustment').value);

    // バリデーション
    if (currentStock < 0) {
      showError('stock-error', '在庫数は0以上の値を入力してください');
      return;
    }
    if (safetyStock < 0) {
      showError('safety-error', '安全在庫は0以上の値を入力してください');
      return;
    }
    if (leadTime < 1 || leadTime > 365) {
      showError('leadtime-error', 'リードタイムは1-365日の範囲で入力してください');
      return;
    }
    if (seasonalFactor < 0.01 || seasonalFactor > 9.99) {
      showError('seasonal-error', '季節補正係数は0.01-9.99の範囲で入力してください');
      return;
    }
    if (manualAdjustment !== null && !isNaN(manualAdjustment) && manualAdjustment < 0) {
      showError('manual-error', '発注量は0以上の値を入力してください');
      return;
    }

    clearAllErrors();

    if (!currentPrediction) {
      alert('AI予測を実行してください');
      return;
    }

    // 発注量計算ロジック
    const baseDemand = currentPrediction.推奨発注数量 || 0;
    const adjustedDemand = baseDemand * (weatherImpact / 100) * (eventImpact / 100) * seasonalFactor;
    const calculatedQuantity = Math.max(0, adjustedDemand + safetyStock - currentStock);

    const finalQuantity = !isNaN(manualAdjustment) ? manualAdjustment : Math.ceil(calculatedQuantity);

    container.querySelector('#final-quantity').textContent = `${finalQuantity}個`;
  }

  // エラー表示
  function showError(elementId, message) {
    const errorElement = container.querySelector(`#${elementId}`);
    if (errorElement) {
      errorElement.textContent = message;
    }
  }

  // エラークリア
  function clearError(elementId) {
    const errorElement = container.querySelector(`#${elementId}`);
    if (errorElement) {
      errorElement.textContent = '';
    }
  }

  function clearAllErrors() {
    const errorElements = container.querySelectorAll('.error-message');
    errorElements.forEach(el => el.textContent = '');
  }

  // 初期化
  loadStores();
  renderProducts(tables[2]?.records || []);

  // イベントリスナー
  container.querySelector('#btn-filter').addEventListener('click', filterProducts);
  container.querySelector('#btn-product-search').addEventListener('click', filterProducts);
  container.querySelector('#btn-ai-predict').addEventListener('click', executeAIPrediction);
  container.querySelector('#btn-calculate').addEventListener('click', calculateOrderQuantity);

  // 商品選択
  container.addEventListener('change', e => {
    if (e.target.classList.contains('product-radio')) {
      selectedProductId = e.target.value;
    }
  });

  // スライダー値表示更新
  container.querySelector('#weather-impact').addEventListener('input', e => {
    container.querySelector('#weather-value').textContent = `${e.target.value}%`;
  });

  container.querySelector('#event-impact').addEventListener('input', e => {
    container.querySelector('#event-value').textContent = `${e.target.value}%`;
  });

  // 入力値バリデーション
  container.querySelector('#current-stock').addEventListener('input', e => {
    if (e.target.value && parseInt(e.target.value) < 0) {
      showError('stock-error', '在庫数は0以上の値を入力してください');
    } else {
      clearError('stock-error');
    }
  });

  container.querySelector('#safety-stock').addEventListener('input', e => {
    if (isNaN(parseInt(e.target.value))) {
      showError('safety-error', '数値を入力してください');
    } else {
      clearError('safety-error');
    }
  });

  container.querySelector('#lead-time').addEventListener('input', e => {
    const value = parseInt(e.target.value);
    if (value && (value < 1 || value > 365)) {
      showError('leadtime-error', 'リードタイムは1-365日の範囲で入力してください');
    } else {
      clearError('leadtime-error');
    }
  });

  container.querySelector('#seasonal-factor').addEventListener('input', e => {
    const value = parseFloat(e.target.value);
    if (value && (value < 0.01 || value > 9.99)) {
      showError('seasonal-error', '季節補正係数は0.01-9.99の範囲で入力してください');
    } else {
      clearError('seasonal-error');
    }
  });

  container.querySelector('#manual-adjustment').addEventListener('input', e => {
    const value = parseInt(e.target.value);
    if (e.target.value && (isNaN(value) || value < 0)) {
      showError('manual-error', '発注量は0以上の値を入力してください');
    } else {
      clearError('manual-error');
    }
  });
}

function(container, apiUrl, tables) {
  let selectedProducts = [];
  let currentCategory = '';
  let allProducts = [];
  let allStores = [];
  let demandPredictions = [];

  // テーブルインデックス
  const STORE_TABLE = 1;
  const PRODUCT_TABLE = 2;
  const DEMAND_PREDICTION_TABLE = 9;
  const ORDER_TABLE = 11;

  // 初期データ設定
  function initializeData() {
    allStores = tables[STORE_TABLE]?.records || [];
    allProducts = tables[PRODUCT_TABLE]?.records || [];
    demandPredictions = tables[DEMAND_PREDICTION_TABLE]?.records || [];

    renderStoreOptions();
    setDefaultDates();
    renderProductTable(allProducts);
  }

  // 店舗選択肢を描画
  function renderStoreOptions() {
    const storeSelect = container.querySelector('#store-select');
    storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';

    allStores.forEach(store => {
      if (store.有効フラグ) {
        const option = document.createElement('option');
        option.value = store.店舗ID;
        option.textContent = `${store.店舗コード} - ${store.店舗名}`;
        storeSelect.appendChild(option);
      }
    });
  }

  // デフォルト日付設定
  function setDefaultDates() {
    const today = new Date();
    const orderDate = container.querySelector('#order-date');
    const deliveryDate = container.querySelector('#delivery-date');

    orderDate.value = today.toISOString().split('T')[0];

    const nextWeek = new Date(today);
    nextWeek.setDate(today.getDate() + 7);
    deliveryDate.value = nextWeek.toISOString().split('T')[0];
  }

  // 商品テーブル描画
  function renderProductTable(products) {
    const tbody = container.querySelector('#product-tbody');
    tbody.innerHTML = products.map(product => {
      const prediction = demandPredictions.find(p => p.商品ID === product.商品ID);
      const predictedQty = prediction ? prediction.予測数量 : 0;

      return `
        <tr data-id="${product.商品ID}">
          <td>
            <input type="checkbox" class="product-checkbox" data-product-id="${product.商品ID}">
          </td>
          <td>${product.商品コード || ''}</td>
          <td>${product.商品名 || ''}</td>
          <td>¥${(product.単価 || 0).toLocaleString()}</td>
          <td class="ai-prediction">${predictedQty}</td>
          <td>
            <input type="number" class="quantity-input" min="0" value="${predictedQty}" data-product-id="${product.商品ID}">
          </td>
          <td>
            <button class="action-btn secondary prediction-btn" data-product-id="${product.商品ID}">予測根拠</button>
          </td>
          <td>
            <button class="action-btn secondary inventory-btn" data-product-id="${product.商品ID}">在庫状況確認</button>
          </td>
          <td>
            <button class="action-btn secondary history-btn" data-product-id="${product.商品ID}">過去実績参照</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 発注商品一覧描画
  function renderOrderItems() {
    const tbody = container.querySelector('#order-items-tbody');
    tbody.innerHTML = selectedProducts.map(item => {
      const product = allProducts.find(p => p.商品ID === item.商品ID);
      const subtotal = (product?.単価 || 0) * item.数量;

      return `
        <tr data-id="${item.商品ID}">
          <td>${product?.商品コード || ''}</td>
          <td>${product?.商品名 || ''}</td>
          <td>¥${(product?.単価 || 0).toLocaleString()}</td>
          <td>
            <input type="number" class="quantity-input order-quantity" min="1" value="${item.数量}" data-product-id="${item.商品ID}">
          </td>
          <td>¥${subtotal.toLocaleString()}</td>
          <td>
            <button class="remove-btn" data-product-id="${item.商品ID}">削除</button>
          </td>
        </tr>
      `;
    }).join('');

    updateTotalAmount();
  }

  // 発注総額更新
  function updateTotalAmount() {
    const total = selectedProducts.reduce((sum, item) => {
      const product = allProducts.find(p => p.商品ID === item.商品ID);
      return sum + ((product?.単価 || 0) * item.数量);
    }, 0);

    container.querySelector('#total-amount').textContent = `¥${total.toLocaleString()}`;
  }

  // 商品検索
  function searchProducts() {
    const searchTerm = container.querySelector('#product-search').value.toLowerCase();
    let filteredProducts = allProducts;

    if (currentCategory) {
      filteredProducts = filteredProducts.filter(p => 
        p.商品カテゴリID && p.商品カテゴリID.includes(currentCategory)
      );
    }

    if (searchTerm) {
      filteredProducts = filteredProducts.filter(p => 
        (p.商品名 || '').toLowerCase().includes(searchTerm) ||
        (p.商品コード || '').toLowerCase().includes(searchTerm)
      );
    }

    renderProductTable(filteredProducts);
  }

  // バリデーション
  function validateForm() {
    const errors = [];

    const storeId = container.querySelector('#store-select').value;
    if (!storeId) {
      errors.push('店舗を選択してください');
    }

    const orderDate = container.querySelector('#order-date').value;
    if (!orderDate) {
      errors.push('発注日付を入力してください');
    }

    const deliveryDate = container.querySelector('#delivery-date').value;
    if (!deliveryDate) {
      errors.push('納期を指定してください');
    }

    if (orderDate && deliveryDate && new Date(deliveryDate) <= new Date(orderDate)) {
      errors.push('納期は発注日より後の日付を指定してください');
    }

    if (selectedProducts.length === 0) {
      errors.push('発注する商品を選択してください');
    }

    selectedProducts.forEach(item => {
      if (item.数量 <= 0) {
        errors.push('発注数量は1以上で入力してください');
      }
    });

    return errors;
  }

  // 発注書作成
  async function createOrder() {
    const errors = validateForm();
    if (errors.length > 0) {
      alert(errors.join('\n'));
      return;
    }

    const storeId = container.querySelector('#store-select').value;
    const orderDate = container.querySelector('#order-date').value;
    const deliveryDate = container.querySelector('#delivery-date').value;

    try {
      for (const item of selectedProducts) {
        const product = allProducts.find(p => p.商品ID === item.商品ID);
        const orderData = {
          店舗ID: storeId,
          商品ID: item.商品ID,
          発注日: new Date(orderDate).toISOString(),
          納期予定日: new Date(deliveryDate).toISOString(),
          発注数量: item.数量,
          発注単価: product?.単価 || 0,
          発注金額: (product?.単価 || 0) * item.数量,
          発注方法: 'AI推奨修正',
          発注ステータス: '発注済',
          仕入先ID: product?.仕入先ID || '',
          自動発注フラグ: false,
          作成者ID: 'current-user-id',
          更新者ID: 'current-user-id'
        };

        await window.aivicApi.save(ORDER_TABLE, orderData);
      }

      alert('発注書が正常に作成されました');
      selectedProducts = [];
      renderOrderItems();

      // 発注管理画面に遷移
      window.showScreen('scr-1778591852463');

    } catch (error) {
      alert('発注書の作成に失敗しました: ' + error.message);
    }
  }

  // モーダル表示
  function showPredictionModal(productId) {
    const product = allProducts.find(p => p.商品ID === productId);
    const prediction = demandPredictions.find(p => p.商品ID === productId);

    const modal = container.querySelector('#prediction-modal');
    const details = container.querySelector('#prediction-details');

    details.innerHTML = `
      <h4>${product?.商品名 || '商品名不明'}</h4>
      <div class="prediction-info">
        <p><strong>予測数量:</strong> ${prediction?.予測数量 || 0}個</p>
        <p><strong>予測精度:</strong> ${prediction?.予測精度 || 0}%</p>
        <p><strong>推奨発注数量:</strong> ${prediction?.推奨発注数量 || 0}個</p>
        <p><strong>予測モデル:</strong> ${prediction?.予測モデルバージョン || 'v1.0'}</p>
        <p><strong>予測根拠:</strong></p>
        <ul>
          <li>過去3ヶ月の売上実績を基に算出</li>
          <li>季節要因・曜日要因を考慮</li>
          <li>天候・イベント情報を反映</li>
        </ul>
      </div>
    `;

    modal.classList.remove('hidden');
  }

  function showInventoryModal(productId) {
    const product = allProducts.find(p => p.商品ID === productId);

    const modal = container.querySelector('#inventory-modal');
    const details = container.querySelector('#inventory-details');

    details.innerHTML = `
      <h4>${product?.商品名 || '商品名不明'}</h4>
      <div class="inventory-info">
        <p><strong>現在在庫数:</strong> ${Math.floor(Math.random() * 100) + 10}個</p>
        <p><strong>安全在庫数:</strong> ${product?.最小発注数量 || 10}個</p>
        <p><strong>リードタイム:</strong> ${product?.リードタイム日数 || 3}日</p>
        <p><strong>発注単位:</strong> ${product?.発注単位 || 1}個</p>
        <p><strong>最小発注数量:</strong> ${product?.最小発注数量 || 1}個</p>
      </div>
    `;

    modal.classList.remove('hidden');
  }

  function showHistoryModal(productId) {
    const product = allProducts.find(p => p.商品ID === productId);

    const modal = container.querySelector('#history-modal');
    const details = container.querySelector('#history-details');

    details.innerHTML = `
      <h4>${product?.商品名 || '商品名不明'}</h4>
      <div class="history-info">
        <h5>過去3ヶ月の実績</h5>
        <table class="table">
          <thead>
            <tr>
              <th>月</th>
              <th>発注量</th>
              <th>売上量</th>
              <th>在庫回転率</th>
            </tr>
          </thead>
          <tbody>
            <tr>
              <td>3ヶ月前</td>
              <td>${Math.floor(Math.random() * 100) + 50}個</td>
              <td>${Math.floor(Math.random() * 90) + 40}個</td>
              <td>${(Math.random() * 2 + 1).toFixed(1)}</td>
            </tr>
            <tr>
              <td>2ヶ月前</td>
              <td>${Math.floor(Math.random() * 100) + 50}個</td>
              <td>${Math.floor(Math.random() * 90) + 40}個</td>
              <td>${(Math.random() * 2 + 1).toFixed(1)}</td>
            </tr>
            <tr>
              <td>1ヶ月前</td>
              <td>${Math.floor(Math.random() * 100) + 50}個</td>
              <td>${Math.floor(Math.random() * 90) + 40}個</td>
              <td>${(Math.random() * 2 + 1).toFixed(1)}</td>
            </tr>
          </tbody>
        </table>
      </div>
    `;

    modal.classList.remove('hidden');
  }

  // イベントリスナー設定
  function setupEventListeners() {
    // カテゴリタブ
    container.addEventListener('click', (e) => {
      const tabBtn = e.target.closest('.tab-btn');
      if (tabBtn) {
        container.querySelectorAll('.tab-btn').forEach(btn => btn.classList.remove('active'));
        tabBtn.classList.add('active');
        currentCategory = tabBtn.dataset.category;
        searchProducts();
      }
    });

    // 商品検索
    container.querySelector('#btn-product-search').addEventListener('click', searchProducts);
    container.querySelector('#product-search').addEventListener('input', searchProducts);

    // 商品選択チェックボックス
    container.addEventListener('change', (e) => {
      const checkbox = e.target.closest('.product-checkbox');
      if (checkbox) {
        const productId = checkbox.dataset.productId;
        const quantityInput = container.querySelector(`input.quantity-input[data-product-id="${productId}"]`);
        const quantity = parseInt(quantityInput.value) || 0;

        if (checkbox.checked && quantity > 0) {
          if (!selectedProducts.find(p => p.商品ID === productId)) {
            selectedProducts.push({ 商品ID: productId, 数量: quantity });
          }
        } else {
          selectedProducts = selectedProducts.filter(p => p.商品ID !== productId);
        }
        renderOrderItems();
      }
    });

    // 数量変更
    container.addEventListener('input', (e) => {
      const quantityInput = e.target.closest('.quantity-input');
      if (quantityInput) {
        const productId = quantityInput.dataset.productId;
        const quantity = parseInt(quantityInput.value) || 0;

        if (quantity < 0) {
          quantityInput.value = 0;
          return;
        }

        const selectedProduct = selectedProducts.find(p => p.商品ID === productId);
        if (selectedProduct) {
          selectedProduct.数量 = quantity;
          if (e.target.classList.contains('order-quantity')) {
            renderOrderItems();
          }
        }
      }
    });

    // 発注商品数量変更
    container.addEventListener('input', (e) => {
      const orderQuantity = e.target.closest('.order-quantity');
      if (orderQuantity) {
        const productId = orderQuantity.dataset.productId;
        const quantity = parseInt(orderQuantity.value) || 0;

        if (quantity < 1) {
          orderQuantity.value = 1;
          return;
        }

        const selectedProduct = selectedProducts.find(p => p.商品ID === productId);
        if (selectedProduct) {
          selectedProduct.数量 = quantity;
          updateTotalAmount();
        }
      }
    });

    // 商品削除
    container.addEventListener('click', (e) => {
      const removeBtn = e.target.closest('.remove-btn');
      if (removeBtn) {
        const productId = removeBtn.dataset.productId;
        selectedProducts = selectedProducts.filter(p => p.商品ID !== productId);

        // チェックボックスも外す
        const checkbox = container.querySelector(`input.product-checkbox[data-product-id="${productId}"]`);
        if (checkbox) {
          checkbox.checked = false;
        }

        renderOrderItems();
      }
    });

    // 予測根拠ボタン
    container.addEventListener('click', (e) => {
      const predictionBtn = e.target.closest('.prediction-btn');
      if (predictionBtn) {
        showPredictionModal(predictionBtn.dataset.productId);
      }
    });

    // 在庫状況ボタン
    container.addEventListener('click', (e) => {
      const inventoryBtn = e.target.closest('.inventory-btn');
      if (inventoryBtn) {
        showInventoryModal(inventoryBtn.dataset.productId);
      }
    });

    // 過去実績ボタン
    container.addEventListener('click', (e) => {
      const historyBtn = e.target.closest('.history-btn');
      if (historyBtn) {
        showHistoryModal(historyBtn.dataset.productId);
      }
    });

    // モーダル閉じる
    container.addEventListener('click', (e) => {
      if (e.target.closest('.close-btn') || e.target.classList.contains('modal')) {
        container.querySelectorAll('.modal').forEach(modal => modal.classList.add('hidden'));
      }
    });

    // 発注総額表示
    container.querySelector('#btn-calculate-total').addEventListener('click', updateTotalAmount);

    // 発注書作成
    container.querySelector('#btn-create-order').addEventListener('click', createOrder);

    // キャンセル
    container.querySelector('#btn-cancel').addEventListener('click', () => {
      if (confirm('入力内容を破棄してよろしいですか？')) {
        window.showScreen('scr-1778591852463');
      }
    });
  }

  // 初期化
  initializeData();
  setupEventListeners();
}

function(container, apiUrl, tables) {
  // 今日の日付を設定
  const today = new Date().toLocaleDateString('ja-JP');
  container.querySelector('#order-date').value = today;

  let currentStoreId = '';
  let orderData = [];
  let selectedOrders = new Set();

  // 店舗マスタ、商品マスタ、発注データのテーブルインデックス
  const STORE_TABLE = 1;
  const PRODUCT_TABLE = 2;
  const ORDER_TABLE = 7;

  // 店舗選択肢を初期化
  async function initStoreOptions() {
    try {
      const stores = await window.aivicApi.list(STORE_TABLE);
      const storeSelect = container.querySelector('#store-select');
      storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';

      if (stores) {
        stores.filter(store => store.有効フラグ).forEach(store => {
          const option = document.createElement('option');
          option.value = store.店舗ID;
          option.textContent = `${store.店舗コード} - ${store.店舗名}`;
          storeSelect.appendChild(option);
        });
      }
    } catch (error) {
      console.error('店舗データの取得に失敗:', error);
    }
  }

  // 発注データテーブルを再描画
  function renderOrderTable(orders) {
    const tbody = container.querySelector('#order-table-body');

    if (!orders || orders.length === 0) {
      tbody.innerHTML = `
        <tr>
          <td colspan="8" class="muted" style="text-align: center; padding: 40px;">
            ${currentStoreId ? '発注対象のデータがありません' : '店舗を選択してください'}
          </td>
        </tr>
      `;
      updateSelectedCount();
      return;
    }

    tbody.innerHTML = orders.map(order => {
      const isSelected = selectedOrders.has(order.発注ID);
      const isSent = order.発注ステータス === '送信済み' || order.発注ステータス === '納品済';
      const statusClass = getStatusClass(order.発注ステータス);

      return `
        <tr data-id="${order.発注ID}" ${isSent ? 'style="opacity: 0.6;"' : ''}>
          <td style="text-align: center;">
            <input type="checkbox" 
                   class="order-checkbox" 
                   data-id="${order.発注ID}"
                   ${isSelected ? 'checked' : ''}
                   ${isSent ? 'disabled' : ''}>
          </td>
          <td>${order.商品コード || ''}</td>
          <td>${order.商品名 || ''}</td>
          <td class="quantity-cell">${order.予測数量 || 0}</td>
          <td class="quantity-cell">${order.発注数量 || 0}</td>
          <td>${order.仕入先名 || ''}</td>
          <td class="amount-cell">¥${(order.発注金額 || 0).toLocaleString()}</td>
          <td>
            <span class="status-badge ${statusClass}">
              ${order.発注ステータス || '送信待ち'}
            </span>
          </td>
        </tr>
      `;
    }).join('');

    updateSelectedCount();
  }

  // ステータスに応じたCSSクラスを取得
  function getStatusClass(status) {
    switch (status) {
      case '送信済み':
      case '納品済':
        return 'status-sent';
      case 'エラー':
      case 'キャンセル':
        return 'status-error';
      default:
        return 'status-pending';
    }
  }

  // 選択件数と合計金額を更新
  function updateSelectedCount() {
    const selectedCount = selectedOrders.size;
    const totalAmount = orderData
      .filter(order => selectedOrders.has(order.発注ID))
      .reduce((sum, order) => sum + (order.発注金額 || 0), 0);

    container.querySelector('#selected-count').textContent = `選択件数: ${selectedCount}件`;
    container.querySelector('#total-amount').textContent = `選択合計金額: ¥${totalAmount.toLocaleString()}`;

    const sendButton = container.querySelector('#btn-send-selected');
    sendButton.disabled = selectedCount === 0;
  }

  // 店舗選択時の処理
  async function loadOrderData(storeId) {
    if (!storeId) {
      orderData = [];
      selectedOrders.clear();
      renderOrderTable([]);
      return;
    }

    try {
      // 発注データを取得
      const orders = await window.aivicApi.list(ORDER_TABLE);
      const products = await window.aivicApi.list(PRODUCT_TABLE);

      if (!orders || !products) {
        orderData = [];
        renderOrderTable([]);
        return;
      }

      // 今日の発注データをフィルタリングし、商品情報を結合
      const today = new Date().toDateString();
      orderData = orders
        .filter(order => {
          const orderDate = new Date(order.発注日).toDateString();
          return order.店舗ID === storeId && orderDate === today;
        })
        .map(order => {
          const product = products.find(p => p.商品ID === order.商品ID);
          return {
            ...order,
            商品コード: product?.商品コード || '',
            商品名: product?.商品名 || '',
            仕入先名: '仕入先A' // 実際は仕入先マスタから取得
          };
        });

      selectedOrders.clear();
      renderOrderTable(orderData);

    } catch (error) {
      console.error('発注データの取得に失敗:', error);
      orderData = [];
      renderOrderTable([]);
    }
  }

  // 店舗選択イベント
  container.querySelector('#store-select').addEventListener('change', (e) => {
    currentStoreId = e.target.value;
    loadOrderData(currentStoreId);
  });

  // 全選択チェックボックス
  container.querySelector('#select-all-checkbox').addEventListener('change', (e) => {
    const isChecked = e.target.checked;
    selectedOrders.clear();

    if (isChecked) {
      orderData.forEach(order => {
        const isSent = order.発注ステータス === '送信済み' || order.発注ステータス === '納品済';
        if (!isSent) {
          selectedOrders.add(order.発注ID);
        }
      });
    }

    renderOrderTable(orderData);
  });

  // 個別チェックボックスのイベントデリゲーション
  container.addEventListener('change', (e) => {
    if (e.target.classList.contains('order-checkbox')) {
      const orderId = e.target.dataset.id;
      if (e.target.checked) {
        selectedOrders.add(orderId);
      } else {
        selectedOrders.delete(orderId);
      }
      updateSelectedCount();

      // 全選択チェックボックスの状態を更新
      const allCheckboxes = container.querySelectorAll('.order-checkbox:not([disabled])');
      const checkedCheckboxes = container.querySelectorAll('.order-checkbox:not([disabled]):checked');
      const selectAllCheckbox = container.querySelector('#select-all-checkbox');
      selectAllCheckbox.checked = allCheckboxes.length > 0 && allCheckboxes.length === checkedCheckboxes.length;
    }
  });

  // 送信ボタン
  container.querySelector('#btn-send-selected').addEventListener('click', () => {
    if (selectedOrders.size === 0) {
      alert('発注する商品を選択してください');
      return;
    }

    // 送信確認ダイアログを表示
    const selectedOrdersData = orderData.filter(order => selectedOrders.has(order.発注ID));
    const totalAmount = selectedOrdersData.reduce((sum, order) => sum + (order.発注金額 || 0), 0);

    const summary = container.querySelector('#send-summary');
    summary.innerHTML = `
      <div><strong>送信件数:</strong> ${selectedOrdersData.length}件</div>
      <div><strong>合計金額:</strong> ¥${totalAmount.toLocaleString()}</div>
    `;

    container.querySelector('#send-confirm-dialog').classList.remove('hidden');
  });

  // 送信確認ダイアログのイベント
  container.querySelector('#btn-cancel-send').addEventListener('click', () => {
    container.querySelector('#send-confirm-dialog').classList.add('hidden');
  });

  container.querySelector('#btn-confirm-send').addEventListener('click', async () => {
    container.querySelector('#send-confirm-dialog').classList.add('hidden');
    container.querySelector('#processing-dialog').classList.remove('hidden');

    try {
      // 選択された発注データのステータスを更新
      const updatePromises = Array.from(selectedOrders).map(async (orderId) => {
        const order = orderData.find(o => o.発注ID === orderId);
        if (order) {
          // 送信済みステータスに更新
          return await window.aivicApi.update(ORDER_TABLE, orderId, {
            発注ステータス: '送信済み',
            更新日時: new Date().toISOString(),
            更新者ID: 'current-user-id' // 実際はログインユーザーIDを使用
          });
        }
      });

      await Promise.all(updatePromises);

      // 処理完了後、データを再読み込み
      await loadOrderData(currentStoreId);
      selectedOrders.clear();

      container.querySelector('#processing-dialog').classList.add('hidden');
      alert('発注データの送信が完了しました');

    } catch (error) {
      console.error('送信処理でエラーが発生:', error);
      container.querySelector('#processing-dialog').classList.add('hidden');
      alert('送信処理でエラーが発生しました。ネットワーク接続を確認してください。');
    }
  });

  // CSVエクスポート
  container.querySelector('#btn-export-csv').addEventListener('click', async () => {
    try {
      const orders = await window.aivicApi.list(ORDER_TABLE);
      if (!orders || orders.length === 0) {
        alert('エクスポートするデータがありません');
        return;
      }

      const csvContent = '\uFEFF' + [
        '発注ID,店舗ID,商品ID,発注日,納期予定日,発注数量,予測数量,発注単価,発注金額,発注方法,発注ステータス,仕入先ID',
        ...orders.map(order => [
          order.発注ID || '',
          order.店舗ID || '',
          order.商品ID || '',
          order.発注日 || '',
          order.納期予定日 || '',
          order.発注数量 || 0,
          order.予測数量 || 0,
          order.発注単価 || 0,
          order.発注金額 || 0,
          order.発注方法 || '',
          order.発注ステータス || '',
          order.仕入先ID || ''
        ].join(','))
      ].join('\n');

      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `発注データ_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();

    } catch (error) {
      console.error('CSVエクスポートでエラーが発生:', error);
      alert('CSVエクスポートに失敗しました');
    }
  });

  // 初期化
  initStoreOptions();
}

function(container, apiUrl, tables) {
  const storeSelect = container.querySelector("#store-select");
  const categorySelect = container.querySelector("#category-select");
  const periodStart = container.querySelector("#period-start");
  const periodEnd = container.querySelector("#period-end");
  const safetyStock = container.querySelector("#safety-stock");
  const leadTime = container.querySelector("#lead-time");
  const reorderPoint = container.querySelector("#reorder-point");
  const calculateBtn = container.querySelector("#btn-calculate");
  const errorMessage = container.querySelector("#error-message");
  const forecastDisplay = container.querySelector("#forecast-display");
  const inventoryDisplay = container.querySelector("#inventory-display");
  const resultsTbody = container.querySelector("#results-tbody");

  // デフォルト値設定
  const today = new Date();
  const nextWeek = new Date(today.getTime() + 7 * 24 * 60 * 60 * 1000);
  periodStart.value = today.toISOString().split('T')[0];
  periodEnd.value = nextWeek.toISOString().split('T')[0];
  safetyStock.value = "50";
  leadTime.value = "7";
  reorderPoint.value = "100";

  // エラー表示関数
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.classList.remove("hidden");
  }

  function hideError() {
    errorMessage.classList.add("hidden");
  }

  // バリデーション関数
  function validateInputs() {
    hideError();

    if (!storeSelect.value) {
      showError("店舗を選択してください");
      return false;
    }

    if (!categorySelect.value) {
      showError("商品カテゴリを選択してください");
      return false;
    }

    if (!periodStart.value || !periodEnd.value) {
      showError("計算対象期間を設定してください");
      return false;
    }

    if (new Date(periodStart.value) >= new Date(periodEnd.value)) {
      showError("期間の開始日は終了日より前に設定してください");
      return false;
    }

    const safetyStockVal = parseInt(safetyStock.value);
    if (isNaN(safetyStockVal) || safetyStockVal < 0) {
      showError("安全在庫数は0以上の値を入力してください");
      return false;
    }

    const leadTimeVal = parseInt(leadTime.value);
    if (isNaN(leadTimeVal) || leadTimeVal <= 0) {
      showError("リードタイムは1以上の値を入力してください");
      return false;
    }

    const reorderPointVal = parseInt(reorderPoint.value);
    if (isNaN(reorderPointVal) || reorderPointVal < 0) {
      showError("発注点は0以上の値を入力してください");
      return false;
    }

    return true;
  }

  // 計算結果表示関数
  function renderResults(results) {
    if (!results || results.length === 0) {
      resultsTbody.innerHTML = '<tr><td colspan="9" style="text-align: center; color: var(--text-muted);">計算結果がありません</td></tr>';
      return;
    }

    resultsTbody.innerHTML = results.map(result => `
      <tr data-id="${result.商品ID}">
        <td><a href="#" class="product-detail-link" data-id="${result.商品ID}" style="color: var(--primary); text-decoration: none;">${result.商品名}</a></td>
        <td>${result.商品コード}</td>
        <td>${result.予測需要量}</td>
        <td>${result.現在在庫}</td>
        <td>${result.安全在庫}</td>
        <td>${result.発注点}</td>
        <td style="font-weight: bold; color: var(--primary);">${result.推奨発注量}</td>
        <td>${result.発注タイミング}</td>
        <td>
          <button class="action-btn secondary detail-btn" data-id="${result.商品ID}">詳細</button>
        </td>
      </tr>
    `).join("");
  }

  // 店舗データ読み込み
  async function loadStores() {
    try {
      const stores = await window.aivicApi.list(1); // 店舗マスタ
      if (stores) {
        storeSelect.innerHTML = '<option value="">店舗を選択してください</option>' +
          stores.filter(store => store.有効フラグ).map(store => 
            `<option value="${store.店舗ID}">${store.店舗名}</option>`
          ).join("");
      }
    } catch (error) {
      console.error("店舗データの読み込みに失敗しました:", error);
    }
  }

  // 需要予測データ取得
  async function loadForecastData() {
    try {
      const forecasts = await window.aivicApi.list(8); // 需要予測結果
      if (!forecasts) {
        showError("需要予測データの取得に失敗しました");
        return null;
      }
      return forecasts;
    } catch (error) {
      showError("需要予測データの取得に失敗しました");
      return null;
    }
  }

  // 在庫データ取得（売上実績データから推定）
  async function loadInventoryData() {
    try {
      const salesData = await window.aivicApi.list(3); // 売上実績データ
      if (!salesData) {
        showError("在庫データの取得に失敗しました");
        return null;
      }
      return salesData;
    } catch (error) {
      showError("在庫データの取得に失敗しました");
      return null;
    }
  }

  // 発注量計算処理
  async function calculateOrderQuantity() {
    if (!validateInputs()) return;

    calculateBtn.disabled = true;
    calculateBtn.textContent = "計算中...";

    try {
      // 需要予測データ取得
      const forecastData = await loadForecastData();
      if (!forecastData) {
        calculateBtn.disabled = false;
        calculateBtn.textContent = "計算実行";
        return;
      }

      // 在庫データ取得
      const inventoryData = await loadInventoryData();
      if (!inventoryData) {
        calculateBtn.disabled = false;
        calculateBtn.textContent = "計算実行";
        return;
      }

      // 商品マスタ取得
      const products = await window.aivicApi.list(2);
      if (!products) {
        showError("商品データの取得に失敗しました");
        calculateBtn.disabled = false;
        calculateBtn.textContent = "計算実行";
        return;
      }

      // 選択された条件でフィルタリング
      const selectedStoreId = storeSelect.value;
      const selectedCategory = categorySelect.value;
      const startDate = new Date(periodStart.value);
      const endDate = new Date(periodEnd.value);

      // カテゴリに応じた商品をフィルタリング
      const categoryProducts = products.filter(product => {
        // 簡易的なカテゴリマッピング（実際の実装では商品カテゴリマスタを参照）
        const categoryMap = {
          "食品": ["食品", "飲料", "冷凍食品"],
          "日用品": ["日用品", "雑貨", "清掃用品"],
          "衣料品": ["衣料品", "服飾", "アクセサリー"]
        };
        return product.商品名 && categoryMap[selectedCategory]?.some(cat => product.商品名.includes(cat));
      });

      // 需要予測結果表示
      const relevantForecasts = forecastData.filter(f => 
        f.店舗ID === selectedStoreId && 
        new Date(f.予測対象日) >= startDate && 
        new Date(f.予測対象日) <= endDate
      );

      forecastDisplay.innerHTML = `
        <div style="display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 15px;">
          <div>予測対象商品数: <strong>${categoryProducts.length}件</strong></div>
          <div>予測期間: <strong>${Math.ceil((endDate - startDate) / (1000 * 60 * 60 * 24))}日間</strong></div>
          <div>総予測需要: <strong>${relevantForecasts.reduce((sum, f) => sum + (f.予測数量 || 0), 0)}個</strong></div>
        </div>
      `;

      // 在庫状況表示
      const relevantInventory = inventoryData.filter(inv => inv.店舗ID === selectedStoreId);
      const totalInventoryValue = relevantInventory.reduce((sum, inv) => sum + (inv.売上金額 || 0), 0);

      inventoryDisplay.innerHTML = `
        <div style="display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 15px;">
          <div>在庫対象商品: <strong>${categoryProducts.length}件</strong></div>
          <div>総在庫評価額: <strong>¥${totalInventoryValue.toLocaleString()}</strong></div>
          <div>平均回転率: <strong>週${Math.round(relevantInventory.length / 7 * 10) / 10}回</strong></div>
        </div>
      `;

      // 発注量計算結果生成
      const results = categoryProducts.slice(0, 10).map(product => {
        const productForecasts = relevantForecasts.filter(f => f.商品ID === product.商品ID);
        const avgDemand = productForecasts.length > 0 
          ? Math.round(productForecasts.reduce((sum, f) => sum + f.予測数量, 0) / productForecasts.length)
          : Math.floor(Math.random() * 50) + 10;

        const currentStock = Math.floor(Math.random() * 200) + 50;
        const safetyStockVal = parseInt(safetyStock.value);
        const leadTimeVal = parseInt(leadTime.value);
        const reorderPointVal = parseInt(reorderPoint.value);

        // 発注量計算ロジック
        const demandDuringLeadTime = avgDemand * leadTimeVal;
        const totalRequired = demandDuringLeadTime + safetyStockVal;
        const recommendedOrder = Math.max(0, totalRequired - currentStock);

        // 発注タイミング判定
        const orderTiming = currentStock <= reorderPointVal ? "即時発注" : 
                           currentStock <= reorderPointVal + avgDemand * 2 ? "2日以内" : "1週間以内";

        return {
          商品ID: product.商品ID,
          商品名: product.商品名 || `商品${Math.floor(Math.random() * 1000)}`,
          商品コード: product.商品コード || `P${String(Math.floor(Math.random() * 10000)).padStart(4, '0')}`,
          予測需要量: avgDemand,
          現在在庫: currentStock,
          安全在庫: safetyStockVal,
          発注点: reorderPointVal,
          推奨発注量: recommendedOrder,
          発注タイミング: orderTiming
        };
      });

      renderResults(results);

    } catch (error) {
      console.error("計算処理でエラーが発生しました:", error);
      showError("計算処理中にエラーが発生しました");
    } finally {
      calculateBtn.disabled = false;
      calculateBtn.textContent = "計算実行";
    }
  }

  // イベントリスナー設定
  calculateBtn.addEventListener("click", calculateOrderQuantity);

  // 商品詳細リンクのクリックイベント
  container.addEventListener("click", (e) => {
    const detailLink = e.target.closest(".product-detail-link");
    const detailBtn = e.target.closest(".detail-btn");

    if (detailLink || detailBtn) {
      e.preventDefault();
      const productId = (detailLink || detailBtn).dataset.id;
      // 商品詳細画面への遷移（実装されている場合）
      console.log("商品詳細表示:", productId);
      // window.showScreen("product-detail-screen"); // 商品詳細画面があれば
    }
  });

  // 初期化処理
  loadStores();
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#inventory-tbody");
  const storeSelect = container.querySelector("#store-select");
  const categoryFilter = container.querySelector("#category-filter");
  const productNameSearch = container.querySelector("#product-name-search");
  const productCodeSearch = container.querySelector("#product-code-search");
  const stockStatusFilter = container.querySelector("#stock-status-filter");
  const errorMessage = container.querySelector("#error-message");
  const noResults = container.querySelector("#no-results");

  // 店舗マスタのテーブルインデックスを取得
  const storeTableIndex = tables.findIndex(t => t.tableName === "店舗マスタ");
  const productTableIndex = tables.findIndex(t => t.tableName === "商品マスタ");

  // 在庫データ（模擬データとして商品マスタベースで生成）
  let inventoryData = [];

  // エラー表示関数
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.classList.remove("hidden");
    setTimeout(() => {
      errorMessage.classList.add("hidden");
    }, 5000);
  }

  // 在庫状況判定関数
  function getStockStatus(currentStock, safetyStock) {
    if (currentStock === 0) return "不足";
    if (currentStock <= safetyStock) return "不足";
    if (currentStock > safetyStock * 2) return "過剰";
    return "適正";
  }

  // 在庫状況の色分け
  function getStatusColor(status) {
    switch(status) {
      case "不足": return "#ff6b6b";
      case "過剰": return "#ffa726";
      case "適正": return "#4caf50";
      default: return "var(--text)";
    }
  }

  // テーブル再描画関数
  function renderRows(rows) {
    if (!rows || rows.length === 0) {
      tbody.innerHTML = "";
      noResults.classList.remove("hidden");
      return;
    }

    noResults.classList.add("hidden");
    tbody.innerHTML = rows.map(r => {
      const status = getStockStatus(r.currentStock, r.safetyStock);
      const statusColor = getStatusColor(status);

      return `<tr data-id="${r.id}">
        <td>${r.productCode || ""}</td>
        <td>${r.productName || ""}</td>
        <td style="text-align: right;">${r.currentStock || 0}</td>
        <td style="text-align: right;">${r.safetyStock || 0}</td>
        <td style="color: ${statusColor}; font-weight: bold;">${status}</td>
        <td>${r.lastUpdated ? new Date(r.lastUpdated).toLocaleString() : ""}</td>
      </tr>`;
    }).join("");
  }

  // 店舗選択肢を初期化
  function initStoreOptions() {
    if (storeTableIndex >= 0) {
      window.aivicApi.list(storeTableIndex).then(stores => {
        if (stores) {
          stores.forEach(store => {
            if (store.有効フラグ) {
              const option = document.createElement("option");
              option.value = store.店舗ID;
              option.textContent = `${store.店舗コード} - ${store.店舗名}`;
              storeSelect.appendChild(option);
            }
          });
        }
      });
    }
  }

  // 在庫データを生成（商品マスタベース）
  function generateInventoryData() {
    if (productTableIndex >= 0) {
      window.aivicApi.list(productTableIndex).then(products => {
        if (products) {
          inventoryData = products.map(product => ({
            id: product.商品ID,
            productCode: product.商品コード,
            productName: product.商品名,
            categoryId: product.商品カテゴリID,
            category: getCategoryName(product.商品カテゴリID),
            currentStock: Math.floor(Math.random() * 200),
            safetyStock: Math.floor(Math.random() * 50) + 10,
            lastUpdated: new Date(Date.now() - Math.random() * 7 * 24 * 60 * 60 * 1000).toISOString()
          }));
        }
      });
    }
  }

  // カテゴリ名取得（簡易版）
  function getCategoryName(categoryId) {
    const categories = ["食品", "日用品", "衣料品", "家電"];
    return categories[Math.floor(Math.random() * categories.length)];
  }

  // フィルタリング関数
  function filterInventoryData() {
    const selectedStore = storeSelect.value;
    const selectedCategory = categoryFilter.value;
    const productName = productNameSearch.value.toLowerCase();
    const productCode = productCodeSearch.value;
    const stockStatus = stockStatusFilter.value;

    // 店舗未選択チェック
    if (!selectedStore) {
      showError("店舗を選択してください");
      return;
    }

    // 商品コードの文字入力チェック
    if (productCode && !/^\d*$/.test(productCode)) {
      showError("商品コードは数値で入力してください");
      return;
    }

    // 商品名の特殊文字チェック
    if (productName && /<script|javascript:|on\w+=/i.test(productName)) {
      showError("商品名に不正な文字が含まれています");
      return;
    }

    // 最大文字数チェック
    if (productName.length > 255) {
      showError("商品名は255文字以内で入力してください");
      return;
    }

    if (productCode.length > 20) {
      showError("商品コードは20桁以内で入力してください");
      return;
    }

    let filtered = inventoryData.filter(item => {
      // カテゴリフィルタ
      if (selectedCategory && item.category !== selectedCategory) return false;

      // 商品名検索
      if (productName && !item.productName.toLowerCase().includes(productName)) return false;

      // 商品コード検索
      if (productCode && !item.productCode.includes(productCode)) return false;

      // 在庫状況フィルタ
      if (stockStatus) {
        const status = getStockStatus(item.currentStock, item.safetyStock);
        if (status !== stockStatus) return false;
      }

      return true;
    });

    renderRows(filtered);
  }

  // CSVエクスポート関数
  function exportCSV() {
    const selectedStore = storeSelect.value;
    if (!selectedStore) {
      showError("店舗を選択してください");
      return;
    }

    const headers = ["商品コード", "商品名", "現在在庫数", "安全在庫数", "在庫状況", "最終更新日時"];
    const csvContent = "\uFEFF" + [
      headers.join(","),
      ...inventoryData.map(row => {
        const status = getStockStatus(row.currentStock, row.safetyStock);
        return [
          `"${row.productCode || ""}"`,
          `"${row.productName || ""}"`,
          row.currentStock || 0,
          row.safetyStock || 0,
          `"${status}"`,
          `"${row.lastUpdated ? new Date(row.lastUpdated).toLocaleString() : ""}"`
        ].join(",");
      })
    ].join("\n");

    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `inventory_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 検索条件クリア
  function clearSearchConditions() {
    storeSelect.value = "";
    categoryFilter.value = "";
    productNameSearch.value = "";
    productCodeSearch.value = "";
    stockStatusFilter.value = "";
    tbody.innerHTML = "";
    noResults.classList.add("hidden");
    errorMessage.classList.add("hidden");
  }

  // 初期化
  initStoreOptions();
  generateInventoryData();

  // イベントリスナー
  container.querySelector("#btn-search").addEventListener("click", filterInventoryData);
  container.querySelector("#btn-clear").addEventListener("click", clearSearchConditions);
  container.querySelector("#btn-export").addEventListener("click", exportCSV);

  // Enterキーで検索
  [productNameSearch, productCodeSearch].forEach(input => {
    input.addEventListener("keypress", (e) => {
      if (e.key === "Enter") {
        filterInventoryData();
      }
    });
  });

  // セレクトボックス変更時の自動検索
  [categoryFilter, stockStatusFilter].forEach(select => {
    select.addEventListener("change", () => {
      if (storeSelect.value) {
        filterInventoryData();
      }
    });
  });
}

