        <td style="text-align: right;">${item.currentStock || 0}</td>
        <td>
          <input type="number" class="input quantity-input" data-product-id="${item.productId}" 
                 value="${item.orderQuantity || 0}" min="0" max="99999" style="width: 100px;">
        </td>
        <td style="text-align: right;">¥${(item.unitPrice || 0).toLocaleString()}</td>
        <td style="text-align: right;" class="order-amount" data-product-id="${item.productId}">
          ¥${((item.orderQuantity || 0) * (item.unitPrice || 0)).toLocaleString()}
        </td>
      </tr>
    `).join('');

    updateTotalAmount();
  }

  // 合計金額更新
  function updateTotalAmount() {
    const checkboxes = container.querySelectorAll('.product-checkbox:checked');
    const selectedCountEl = container.querySelector('#selected-count');
    const totalAmountEl = container.querySelector('#total-amount');
    const bulkOrderBtn = container.querySelector('#btn-bulk-order');

    let totalAmount = 0;
    let selectedCount = 0;

    checkboxes.forEach(checkbox => {
      const productId = checkbox.dataset.productId;
      const quantityInput = container.querySelector(`.quantity-input[data-product-id="${productId}"]`);
      const quantity = parseInt(quantityInput.value) || 0;
      const item = currentOrderData.find(d => d.productId === productId);
      if (item && quantity > 0) {
        totalAmount += quantity * (item.unitPrice || 0);
        selectedCount++;
      }
    });

    selectedCountEl.textContent = selectedCount;
    totalAmountEl.textContent = `¥${totalAmount.toLocaleString()}`;
    bulkOrderBtn.disabled = selectedCount === 0;
  }

  // 発注データ生成
  function generateOrderData(storeId, orderDate) {
    if (!storeId) return [];

    const orderItems = [];

    // 需要予測データから発注対象商品を抽出
    demandForecastData.forEach(forecast => {
      if (forecast.店舗ID !== storeId) return;

      const product = productsData.find(p => p.商品ID === forecast.商品ID);
      if (!product || !product.有効フラグ) return;

      // 現在在庫を取得（仮想データ）
      const currentStock = Math.floor(Math.random() * 50);

      const orderItem = {
        productId: product.商品ID,
        productCode: product.商品コード,
        productName: product.商品名,
        forecastQuantity: forecast.予測数量 || 0,
        recommendedQuantity: forecast.推奨発注数量 || 0,
        currentStock: currentStock,
        orderQuantity: forecast.推奨発注数量 || 0,
        unitPrice: product.単価 || 0
      };

      orderItems.push(orderItem);
    });

    return orderItems;
  }

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      // 店舗データ読み込み
      const stores = await window.aivicApi.list(1); // 店舗マスタ
      if (stores) {
        storesData = stores;
        const storeSelect = container.querySelector('#store-select');
        storeSelect.innerHTML = '<option value="">店舗を選択してください</option>' +
          stores.filter(s => s.有効フラグ).map(store => 
            `<option value="${store.店舗ID}">${store.店舗名}</option>`
          ).join('');
      }

      // 商品データ読み込み
      const products = await window.aivicApi.list(2); // 商品マスタ
      if (products) {
        productsData = products;

        // カテゴリフィルター設定（仮想カテゴリ）
        const categories = ['食品', '日用品', '衣料品', '家電', 'その他'];
        const categorySelect = container.querySelector('#category-filter');
        categorySelect.innerHTML = '<option value="">全てのカテゴリ</option>' +
          categories.map(cat => `<option value="${cat}">${cat}</option>`).join('');
      }

      // 需要予測データ読み込み
      const forecasts = await window.aivicApi.list(8); // 需要予測結果
      if (forecasts) {
        demandForecastData = forecasts;
      }

    } catch (error) {
      console.error('データ読み込みエラー:', error);
      showError('データの読み込みに失敗しました');
    }
  }

  // 店舗選択変更イベント
  container.querySelector('#store-select').addEventListener('change', function() {
    const storeId = this.value;
    const orderDate = container.querySelector('#order-date').value;

    if (storeId && orderDate) {
      currentOrderData = generateOrderData(storeId, orderDate);
      renderOrderTable(currentOrderData);
    } else {
      renderOrderTable([]);
    }
  });

  // 発注日付変更イベント
  container.querySelector('#order-date').addEventListener('change', function() {
    const orderDate = this.value;
    const today = new Date().toISOString().split('T')[0];

    if (orderDate < today) {
      showError('発注日付は本日以降の日付を選択してください');
      this.value = today;
      return;
    }

    const storeId = container.querySelector('#store-select').value;
    if (storeId && orderDate) {
      currentOrderData = generateOrderData(storeId, orderDate);
      renderOrderTable(currentOrderData);
    }
  });

  // カテゴリフィルター変更イベント
  container.querySelector('#category-filter').addEventListener('change', function() {
    const category = this.value;
    const storeId = container.querySelector('#store-select').value;

    if (!storeId) return;

    let filteredData = currentOrderData;
    if (category) {
      // 仮想的なカテゴリフィルタリング
      filteredData = currentOrderData.filter(item => {
        const productName = item.productName.toLowerCase();
        switch(category) {
          case '食品': return productName.includes('食') || productName.includes('パン') || productName.includes('米');
          case '日用品': return productName.includes('洗剤') || productName.includes('石鹸') || productName.includes('タオル');
          case '衣料品': return productName.includes('服') || productName.includes('シャツ') || productName.includes('靴');
          case '家電': return productName.includes('電') || productName.includes('機器');
          default: return true;
        }
      });
    }

    renderOrderTable(filteredData);
  });

  // 表示更新ボタン
  container.querySelector('#btn-filter').addEventListener('click', function() {
    const storeId = container.querySelector('#store-select').value;
    const orderDate = container.querySelector('#order-date').value;

    if (!storeId) {
      showError('店舗を選択してください');
      return;
    }

    if (!orderDate) {
      showError('発注日付を選択してください');
      return;
    }

    currentOrderData = generateOrderData(storeId, orderDate);

    // カテゴリフィルターを適用
    const category = container.querySelector('#category-filter').value;
    let filteredData = currentOrderData;
    if (category) {
      filteredData = currentOrderData.filter(item => {
        const productName = item.productName.toLowerCase();
        switch(category) {
          case '食品': return productName.includes('食') || productName.includes('パン') || productName.includes('米');
          case '日用品': return productName.includes('洗剤') || productName.includes('石鹸') || productName.includes('タオル');
          case '衣料品': return productName.includes('服') || productName.includes('シャツ') || productName.includes('靴');
          case '家電': return productName.includes('電') || productName.includes('機器');
          default: return true;
        }
      });
    }

    renderOrderTable(filteredData);
  });

  // 全選択チェックボックス
  container.querySelector('#select-all').addEventListener('change', function() {
    const checkboxes = container.querySelectorAll('.product-checkbox');
    checkboxes.forEach(cb => cb.checked = this.checked);
    updateTotalAmount();
  });

  // 数量入力・チェックボックス変更イベント（イベントデリゲーション）
  container.addEventListener('input', function(e) {
    if (e.target.classList.contains('quantity-input')) {
      const productId = e.target.dataset.productId;
      const quantity = parseInt(e.target.value) || 0;

      // バリデーション
      if (quantity < 0) {
        showError('発注数量は0以上の値を入力してください');
        e.target.value = 0;
        return;
      }

      if (quantity > 99999) {
        showError('発注数量は99999以下で入力してください');
        e.target.value = 99999;
        return;
      }

      if (e.target.value.includes('.')) {
        showError('発注数量は整数で入力してください');
        e.target.value = Math.floor(quantity);
        return;
      }

      // 金額更新
      const item = currentOrderData.find(d => d.productId === productId);
      if (item) {
        const amount = quantity * (item.unitPrice || 0);
        const amountCell = container.querySelector(`.order-amount[data-product-id="${productId}"]`);
        if (amountCell) {
          amountCell.textContent = `¥${amount.toLocaleString()}`;
        }
      }

      updateTotalAmount();
    }
  });

  container.addEventListener('change', function(e) {
    if (e.target.classList.contains('product-checkbox')) {
      updateTotalAmount();
    }
  });

  // まとめて発注実行ボタン
  container.querySelector('#btn-bulk-order').addEventListener('click', function() {
    const storeId = container.querySelector('#store-select').value;
    const orderDate = container.querySelector('#order-date').value;

    if (!storeId) {
      showError('店舗を選択してください');
      return;
    }

    const selectedItems = [];
    const checkboxes = container.querySelectorAll('.product-checkbox:checked');

    checkboxes.forEach(checkbox => {
      const productId = checkbox.dataset.productId;
      const quantityInput = container.querySelector(`.quantity-input[data-product-id="${productId}"]`);
      const quantity = parseInt(quantityInput.value) || 0;

      if (quantity <= 0) {
        showError('発注数量は1以上の値を入力してください');
        return;
      }

      const item = currentOrderData.find(d => d.productId === productId);
      if (item) {
        selectedItems.push({
          ...item,
          orderQuantity: quantity
        });
      }
    });

    if (selectedItems.length === 0) {
      showError('発注する商品を選択してください');
      return;
    }

    showOrderConfirmDialog(selectedItems, storeId, orderDate);
  });

  // 推奨数量で一括発注ボタン
  container.querySelector('#btn-recommended-order').addEventListener('click', function() {
    const storeId = container.querySelector('#store-select').value;
    const orderDate = container.querySelector('#order-date').value;

    if (!storeId) {
      showError('店舗を選択してください');
      return;
    }

    if (currentOrderData.length === 0) {
      showError('発注対象商品がありません');
      return;
    }

    // 推奨数量が0より大きい商品のみを対象
    const recommendedItems = currentOrderData.filter(item => (item.recommendedQuantity || 0) > 0);

    if (recommendedItems.length === 0) {
      showError('推奨発注数量が設定された商品がありません');
      return;
    }

    showOrderConfirmDialog(recommendedItems, storeId, orderDate);
  });

  // 発注確認ダイアログ表示
  function showOrderConfirmDialog(orderItems, storeId, orderDate) {
    const dialog = container.querySelector('#order-confirm-dialog');
    const content = container.querySelector('#order-confirm-content');

    const store = storesData.find(s => s.店舗ID === storeId);
    const storeName = store ? store.店舗名 : '不明な店舗';

    let totalAmount = 0;
    const itemsHtml = orderItems.map(item => {
      const amount = (item.orderQuantity || item.recommendedQuantity || 0) * (item.unitPrice || 0);
      totalAmount += amount;
      return `
        <tr>
          <td>${item.productCode}</td>
          <td>${item.productName}</td>
          <td style="text-align: right;">${item.orderQuantity || item.recommendedQuantity || 0}</td>
          <td style="text-align: right;">¥${(item.unitPrice || 0).toLocaleString()}</td>
          <td style="text-align: right;">¥${amount.toLocaleString()}</td>
        </tr>
      `;
    }).join('');

    content.innerHTML = `
      <div style="margin-bottom: 16px;">
        <p><strong>店舗:</strong> ${storeName}</p>
        <p><strong>発注日:</strong> ${orderDate}</p>
        <p><strong>発注商品数:</strong> ${orderItems.length}件</p>
      </div>
      <div class="table-wrap" style="max-height: 300px; overflow-y: auto;">
        <table>
          <thead>
            <tr>
              <th>商品コード</th>
              <th>商品名</th>
              <th>数量</th>
              <th>単価</th>
              <th>金額</th>
            </tr>
          </thead>
          <tbody>
            ${itemsHtml}
          </tbody>
        </table>
      </div>
      <div style="margin-top: 16px; text-align: right; font-size: 18px; font-weight: bold;">
        合計金額: <span style="color: var(--primary);">¥${totalAmount.toLocaleString()}</span>
      </div>
    `;

    dialog.classList.remove('hidden');

    // 発注実行ボタンにデータを保存
    container.querySelector('#btn-execute-order').orderData = {
      orderItems,
      storeId,
      orderDate,
      totalAmount
    };
  }

  // 発注確認ダイアログのキャンセル
  container.querySelector('#btn-cancel-order').addEventListener('click', function() {
    container.querySelector('#order-confirm-dialog').classList.add('hidden');
  });

  // 発注実行
  container.querySelector('#btn-execute-order').addEventListener('click', async function() {
    const orderData = this.orderData;
    if (!orderData) return;

    try {
      // 各商品の発注データを保存
      for (const item of orderData.orderItems) {
        const orderRecord = {
          店舗ID: orderData.storeId,
          商品ID: item.productId,
          発注日: orderData.orderDate + 'T00:00:00Z',
          納期予定日: new Date(Date.now() + 3 * 24 * 60 * 60 * 1000).toISOString(), // 3日後
          発注数量: item.orderQuantity || item.recommendedQuantity || 0,
          予測数量: item.forecastQuantity || 0,
          発注単価: item.unitPrice || 0,
          発注金額: (item.orderQuantity || item.recommendedQuantity || 0) * (item.unitPrice || 0),
          発注方法: item.orderQuantity ? 'AI推奨修正' : 'AI推奨採用',
          発注ステータス: '発注済',
          仕入先ID: 'supplier-001', // 仮の仕入先ID
          自動発注フラグ: false,
          作成日時: new Date().toISOString(),
          更新日時: new Date().toISOString(),
          作成者ID: 'current-user-id', // 現在のユーザーID
          更新者ID: 'current-user-id'
        };

        await window.aivicApi.save(9, orderRecord); // 発注データテーブル
      }

      // ダイアログを閉じる
      container.querySelector('#order-confirm-dialog').classList.add('hidden');

      // 成功メッセージ表示
      alert(`発注が完了しました。\n発注商品数: ${orderData.orderItems.length}件\n合計金額: ¥${orderData.totalAmount.toLocaleString()}`);

      // 画面をリセット
      container.querySelector('#store-select').value = '';
      renderOrderTable([]);

    } catch (error) {
      console.error('発注実行エラー:', error);
      showError('発注の実行に失敗しました');
    }
  });

  // 初期データ読み込み実行
  loadInitialData();
}

function(container, apiUrl, tables) {
  let currentData = [];
  let sortColumn = 'accuracy';
  let sortDirection = 'desc';

  // テーブル再描画関数
  function renderRows(rows) {
    const tbody = container.querySelector('#accuracy-ranking-tbody');
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr><td colspan="10" class="muted" style="text-align: center;">データがありません</td></tr>';
      return;
    }

    // ソート処理
    const sortedRows = [...rows].sort((a, b) => {
      let aVal = a[sortColumn];
      let bVal = b[sortColumn];

      if (typeof aVal === 'string') {
        aVal = aVal.toLowerCase();
        bVal = bVal.toLowerCase();
      }

      if (sortDirection === 'asc') {
        return aVal > bVal ? 1 : -1;
      } else {
        return aVal < bVal ? 1 : -1;
      }
    });

    tbody.innerHTML = sortedRows.map((row, index) => {
      const accuracy = row.prediction_accuracy || 0;
      const mape = calculateMAPE(row.forecast_quantity, row.actual_quantity);
      const rmse = calculateRMSE(row.forecast_quantity, row.actual_quantity);

      const accuracyColor = accuracy >= 90 ? '#4ade80' : accuracy >= 70 ? '#fbbf24' : '#f87171';

      return `
        <tr data-id="${row.id}">
          <td>${index + 1}</td>
          <td>${getStoreName(row.store_id)}</td>
          <td>${getProductName(row.product_id)}</td>
          <td style="color: ${accuracyColor}; font-weight: bold;">${accuracy.toFixed(1)}%</td>
          <td>${mape.toFixed(2)}%</td>
          <td>${rmse.toFixed(2)}</td>
          <td>${row.forecast_quantity || 0}</td>
          <td>${row.actual_quantity || 0}</td>
          <td>${formatDate(row.prediction_target_date)}</td>
          <td>
            <button class="action-btn secondary detail-btn" data-id="${row.id}">詳細</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // サマリー更新
  function updateSummary(rows) {
    if (!rows || rows.length === 0) {
      container.querySelector('#overall-accuracy').textContent = '--';
      container.querySelector('#mape-value').textContent = '--';
      container.querySelector('#rmse-value').textContent = '--';
      container.querySelector('#monitoring-count').textContent = '0';
      return;
    }

    const totalAccuracy = rows.reduce((sum, row) => sum + (row.prediction_accuracy || 0), 0);
    const avgAccuracy = totalAccuracy / rows.length;

    const totalMAPE = rows.reduce((sum, row) => sum + calculateMAPE(row.forecast_quantity, row.actual_quantity), 0);
    const avgMAPE = totalMAPE / rows.length;

    const totalRMSE = rows.reduce((sum, row) => sum + calculateRMSE(row.forecast_quantity, row.actual_quantity), 0);
    const avgRMSE = totalRMSE / rows.length;

    container.querySelector('#overall-accuracy').textContent = avgAccuracy.toFixed(1) + '%';
    container.querySelector('#mape-value').textContent = avgMAPE.toFixed(2) + '%';
    container.querySelector('#rmse-value').textContent = avgRMSE.toFixed(2);
    container.querySelector('#monitoring-count').textContent = rows.length.toString();

    // アラート判定
    checkAccuracyAlert(avgAccuracy, rows);
  }

  // アラート判定
  function checkAccuracyAlert(avgAccuracy, rows) {
    const alertPanel = container.querySelector('#alert-panel');
    const alertContent = container.querySelector('#alert-content');

    const lowAccuracyItems = rows.filter(row => (row.prediction_accuracy || 0) < 70);

    if (avgAccuracy < 80 || lowAccuracyItems.length > 0) {
      alertContent.innerHTML = `
        <p>予測精度が閾値を下回っています:</p>
        <ul>
          <li>全体平均精度: ${avgAccuracy.toFixed(1)}% (閾値: 80%)</li>
          <li>低精度アイテム数: ${lowAccuracyItems.length}件</li>
        </ul>
        <p>モデルの再学習を検討してください。</p>
      `;
      alertPanel.classList.remove('hidden');
    } else {
      alertPanel.classList.add('hidden');
    }
  }

  // グラフ描画
  function drawAccuracyTrendChart(rows) {
    const canvas = container.querySelector('#accuracy-trend-chart');
    const ctx = canvas.getContext('2d');

    // Canvas サイズ設定
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width * window.devicePixelRatio;
    canvas.height = rect.height * window.devicePixelRatio;
    ctx.scale(window.devicePixelRatio, window.devicePixelRatio);

    const width = rect.width;
    const height = rect.height;
    const padding = 60;

    ctx.clearRect(0, 0, width, height);

    if (!rows || rows.length === 0) {
      ctx.fillStyle = '#9fb0d1';
      ctx.font = '16px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('データがありません', width / 2, height / 2);
      return;
    }

    // データ準備
    const dailyData = {};
    rows.forEach(row => {
      const date = formatDate(row.prediction_target_date);
      if (!dailyData[date]) {
        dailyData[date] = { total: 0, count: 0 };
      }
      dailyData[date].total += (row.prediction_accuracy || 0);
      dailyData[date].count += 1;
    });

    const chartData = Object.keys(dailyData)
      .sort()
      .slice(-30) // 最新30日
      .map(date => ({
        date,
        accuracy: dailyData[date].total / dailyData[date].count
      }));

    if (chartData.length === 0) return;

    // 軸描画
    ctx.strokeStyle = '#4a5568';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, height - padding);
    ctx.lineTo(width - padding, height - padding);
    ctx.stroke();

    // グラフ描画
    if (chartData.length > 1) {
      ctx.strokeStyle = '#3b82f6';
      ctx.lineWidth = 2;
      ctx.beginPath();

      chartData.forEach((point, index) => {
        const x = padding + (index / (chartData.length - 1)) * (width - 2 * padding);
        const y = height - padding - (point.accuracy / 100) * (height - 2 * padding);

        if (index === 0) {
          ctx.moveTo(x, y);
        } else {
          ctx.lineTo(x, y);
        }
      });
      ctx.stroke();

      // データポイント
      ctx.fillStyle = '#3b82f6';
      chartData.forEach((point, index) => {
        const x = padding + (index / (chartData.length - 1)) * (width - 2 * padding);
        const y = height - padding - (point.accuracy / 100) * (height - 2 * padding);

        ctx.beginPath();
        ctx.arc(x, y, 4, 0, 2 * Math.PI);
        ctx.fill();
      });
    }

    // ラベル
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '12px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('予測精度推移 (過去30日)', width / 2, 20);
  }

  function drawForecastActualChart(rows) {
    const canvas = container.querySelector('#forecast-actual-chart');
    const ctx = canvas.getContext('2d');

    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width * window.devicePixelRatio;
    canvas.height = rect.height * window.devicePixelRatio;
    ctx.scale(window.devicePixelRatio, window.devicePixelRatio);

    const width = rect.width;
    const height = rect.height;
    const padding = 60;

    ctx.clearRect(0, 0, width, height);

    if (!rows || rows.length === 0) {
      ctx.fillStyle = '#9fb0d1';
      ctx.font = '16px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('データがありません', width / 2, height / 2);
      return;
    }

    // 軸描画
    ctx.strokeStyle = '#4a5568';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, height - padding);
    ctx.lineTo(width - padding, height - padding);
    ctx.stroke();

    // データ準備
    const chartData = rows.slice(0, 20).map((row, index) => ({
      index,
      forecast: row.forecast_quantity || 0,
      actual: row.actual_quantity || 0
    }));

    if (chartData.length === 0) return;

    const maxValue = Math.max(...chartData.map(d => Math.max(d.forecast, d.actual)));
    const barWidth = (width - 2 * padding) / (chartData.length * 2);

    // 予測値（青）
    ctx.fillStyle = '#3b82f6';
    chartData.forEach((data, index) => {
      const x = padding + index * barWidth * 2;
      const barHeight = (data.forecast / maxValue) * (height - 2 * padding);
      const y = height - padding - barHeight;
      ctx.fillRect(x, y, barWidth * 0.8, barHeight);
    });

    // 実績値（緑）
    ctx.fillStyle = '#10b981';
    chartData.forEach((data, index) => {
      const x = padding + index * barWidth * 2 + barWidth;
      const barHeight = (data.actual / maxValue) * (height - 2 * padding);
      const y = height - padding - barHeight;
      ctx.fillRect(x, y, barWidth * 0.8, barHeight);
    });

    // 凡例
    ctx.fillStyle = '#3b82f6';
    ctx.fillRect(width - 150, 20, 15, 15);
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '12px sans-serif';
    ctx.textAlign = 'left';
    ctx.fillText('予測値', width - 130, 32);

    ctx.fillStyle = '#10b981';
    ctx.fillRect(width - 150, 40, 15, 15);
    ctx.fillStyle = '#9fb0d1';
    ctx.fillText('実績値', width - 130, 52);
  }

  // ヘルパー関数
  function calculateMAPE(forecast, actual) {
    if (!actual || actual === 0) return 0;
    return Math.abs((actual - forecast) / actual) * 100;
  }

  function calculateRMSE(forecast, actual) {
    return Math.sqrt(Math.pow(actual - forecast, 2));
  }

  function getStoreName(storeId) {
    const store = tables[1]?.records?.find(s => s.id === storeId);
    return store?.store_name || '不明な店舗';
  }

  function getProductName(productId) {
    const product = tables[2]?.records?.find(p => p.id === productId);
    return product?.product_name || '不明な商品';
  }

  function formatDate(dateStr) {
    if (!dateStr) return '';
    const date = new Date(dateStr);
    return date.toLocaleDateString('ja-JP');
  }

  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    const errorContent = container.querySelector('#error-content');
    errorContent.textContent = message;
    errorDiv.classList.remove('hidden');
  }

  function hideError() {
    container.querySelector('#error-message').classList.add('hidden');
  }

  // データ読み込み
  async function loadData() {
    try {
      hideError();
      const rows = await window.aivicApi.list(8); // 需要予測結果テーブル
      if (rows) {
        currentData = rows;
        renderRows(rows);
        updateSummary(rows);
        drawAccuracyTrendChart(rows);
        drawForecastActualChart(rows);
      } else {
        showError('データの取得に失敗しました。ネットワーク接続を確認してください。');
      }
    } catch (error) {
      showError('データ取得エラー: ' + error.message);
    }
  }

  // 店舗選択肢の初期化
  function initStoreOptions() {
    const storeSelect = container.querySelector('#store-filter');
    const stores = tables[1]?.records || [];
    stores.forEach(store => {
      const option = document.createElement('option');
      option.value = store.id;
      option.textContent = store.store_name;
      storeSelect.appendChild(option);
    });
  }

  // フィルター適用
  function applyFilters() {
    const period = parseInt(container.querySelector('#period-filter').value);
    const storeId = container.querySelector('#store-filter').value;
    const category = container.querySelector('#category-filter').value;

    let filteredData = [...currentData];

    // 期間フィルター
    const cutoffDate = new Date();
    cutoffDate.setDate(cutoffDate.getDate() - period);
    filteredData = filteredData.filter(row => {
      const rowDate = new Date(row.prediction_target_date);
      return rowDate >= cutoffDate;
    });

    // 店舗フィルター
    if (storeId) {
      filteredData = filteredData.filter(row => row.store_id === storeId);
    }

    // カテゴリフィルター（商品マスタと結合が必要）
    if (category) {
      const categoryProducts = tables[2]?.records?.filter(p => 
        p.product_category_id === category || p.product_name?.includes(category)
      ).map(p => p.id) || [];
      filteredData = filteredData.filter(row => categoryProducts.includes(row.product_id));
    }

    renderRows(filteredData);
    updateSummary(filteredData);
    drawAccuracyTrendChart(filteredData);
    drawForecastActualChart(filteredData);
  }

  // CSVエクスポート
  function exportCSV() {
    const headers = ['順位', '店舗名', '商品名', '予測精度(%)', 'MAPE(%)', 'RMSE', '予測数量', '実績数量', '予測日'];
    const csvData = currentData.map((row, index) => [
      index + 1,
      getStoreName(row.store_id),
      getProductName(row.product_id),
      (row.prediction_accuracy || 0).toFixed(1),
      calculateMAPE(row.forecast_quantity, row.actual_quantity).toFixed(2),
      calculateRMSE(row.forecast_quantity, row.actual_quantity).toFixed(2),
      row.forecast_quantity || 0,
      row.actual_quantity || 0,
      formatDate(row.prediction_target_date)
    ]);

    const csvContent = '\uFEFF' + [headers, ...csvData].map(row => 
      row.map(cell => `"${cell}"`).join(',')
    ).join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `予測精度レポート_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 初期化
  initStoreOptions();
  loadData();

  // イベントリスナー
  container.querySelector('#btn-apply-filter').addEventListener('click', applyFilters);

  container.querySelector('#btn-export-report').addEventListener('click', exportCSV);

  container.querySelector('#btn-detail-analysis').addEventListener('click', () => {
    window.showScreen('scr-1778591838939'); // 需要予測管理画面
  });

  container.querySelector('#btn-retry').addEventListener('click', loadData);

  // ソート機能
  container.addEventListener('click', (e) => {
    const sortable = e.target.closest('.sortable');
    if (sortable) {
      const column = sortable.dataset.column;
      if (sortColumn === column) {
        sortDirection = sortDirection === 'asc' ? 'desc' : 'asc';
      } else {
        sortColumn = column;
        sortDirection = 'desc';
      }

      // ソートインジケーター更新
      container.querySelectorAll('.sortable').forEach(th => {
        th.style.position = 'relative';
        const existing = th.querySelector('.sort-indicator');
        if (existing) existing.remove();
      });

      const indicator = document.createElement('span');
      indicator.className = 'sort-indicator';
      indicator.textContent = sortDirection === 'asc' ? ' ↑' : ' ↓';
      indicator.style.position = 'absolute';
      indicator.style.right = '5px';
      sortable.appendChild(indicator);

      renderRows(currentData);
    }

    // 詳細ボタン
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      window.showScreen('scr-1778591838939'); // 需要予測管理画面
    }
  });

  // オフライン対応
  window.addEventListener('online', () => {
    hideError();
    loadData();
  });

  window.addEventListener('offline', () => {
    showError('ネットワークに接続できません。接続を確認してください。');
  });
}

function(container, apiUrl, tables) {
  let editingModelId = null;

  // 1. 再描画関数の定義
  function renderRows(rows) {
    const tbody = container.querySelector("#model-list-tbody");
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}">
        <td>${r.モデル名 || ""}</td>
        <td>${r.対象店舗 || ""}</td>
        <td>${r.商品カテゴリ || ""}</td>
        <td>${r.アルゴリズム || ""}</td>
        <td>${r.精度目標値 || ""}%</td>
        <td>${r.作成日時 ? new Date(r.作成日時).toLocaleDateString() : ""}</td>
        <td>
          <button class="action-btn secondary edit-btn" data-id="${r.id}">設定変更</button>
          <button class="action-btn secondary delete-btn" data-id="${r.id}">削除</button>
        </td>
      </tr>
    `).join("");
  }

  // 2. 初期データ描画
  renderRows(tables[0].records || []);

  // 店舗データを店舗選択に設定
  const storeSelect = container.querySelector("#target-store");
  if (tables[1] && tables[1].records) {
    tables[1].records.forEach(store => {
      const option = document.createElement("option");
      option.value = store.店舗名;
      option.textContent = store.店舗名;
      storeSelect.appendChild(option);
    });
  }

  // 3. 検索ボタンのイベントリスナー
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const kw = container.querySelector("#input-search").value;
    const rows = await window.aivicApi.list(0);
    if (rows) {
      const filtered = rows.filter(r => JSON.stringify(r).toLowerCase().includes(kw.toLowerCase()));
      renderRows(filtered);
    }
  });

  // 新規モデル作成ボタン
  container.querySelector("#btn-new-model").addEventListener("click", () => {
    editingModelId = null;
    container.querySelector("#form-title").textContent = "新規モデル作成";
    container.querySelector("#btn-save-model").textContent = "モデル作成";
    container.querySelector("#model-form").reset();
    container.querySelector("#model-form-card").classList.remove("hidden");
    updateWeightTotal();
  });

  // キャンセルボタン
  container.querySelector("#btn-cancel").addEventListener("click", () => {
    container.querySelector("#model-form-card").classList.add("hidden");
    container.querySelector("#model-form").reset();
    editingModelId = null;
  });

  // 学習率スライダーの値表示更新
  const learningRateSlider = container.querySelector("#learning-rate");
  const learningRateValue = container.querySelector("#learning-rate-value");
  learningRateSlider.addEventListener("input", () => {
    learningRateValue.textContent = learningRateSlider.value;
  });

  // 重み付けの合計値計算
  function updateWeightTotal() {
    const weights = container.querySelectorAll(".weight-input");
    let total = 0;
    weights.forEach(input => {
      total += parseInt(input.value) || 0;
    });
    const totalSpan = container.querySelector("#weight-total");
    totalSpan.textContent = total;
    totalSpan.style.color = total === 100 ? "var(--text)" : "#ff6a6a";
  }

  // 重み付け入力の変更監視
  container.querySelectorAll(".weight-input").forEach(input => {
    input.addEventListener("input", updateWeightTotal);
  });

  // 全選択チェックボックス
  container.querySelector("#select-all-datasources").addEventListener("change", (e) => {
    const checkboxes = container.querySelectorAll("#datasource-checkboxes input[type='checkbox']");
    checkboxes.forEach(cb => cb.checked = e.target.checked);
  });

  // バリデーション関数
  function validateForm() {
    const errors = [];

    // モデル名チェック
    const modelName = container.querySelector("#model-name").value.trim();
    if (!modelName) {
      errors.push("モデル名を入力してください");
    }

    // 対象店舗チェック
    const targetStore = container.querySelector("#target-store").value;
    if (!targetStore) {
      errors.push("対象店舗を選択してください");
    }

    // 商品カテゴリチェック
    const categories = container.querySelectorAll("#category-checkboxes input[type='checkbox']:checked");
    if (categories.length === 0) {
      errors.push("商品カテゴリを選択してください");
    }

    // 学習期間チェック
    const startDate = container.querySelector("#learning-start-date").value;
    const endDate = container.querySelector("#learning-end-date").value;
    if (!startDate || !endDate) {
      errors.push("学習期間を設定してください");
    } else {
      const start = new Date(startDate);
      const end = new Date(endDate);
      const today = new Date();

      if (start > end) {
        errors.push("開始日は終了日より前の日付を設定してください");
      }
      if (start > today || end > today) {
        errors.push("学習期間に未来の日付は設定できません");
      }
    }

    // 予測期間チェック
    const predictionPeriod = container.querySelector("input[name='prediction-period']:checked");
    if (!predictionPeriod) {
      errors.push("予測期間を選択してください");
    }

    // データソースチェック
    const dataSources = container.querySelectorAll("#datasource-checkboxes input[type='checkbox']:checked");
    if (dataSources.length === 0) {
      errors.push("データソースを選択してください");
    }

    // アルゴリズムチェック
    const algorithm = container.querySelector("#algorithm-type").value;
    if (!algorithm) {
      errors.push("アルゴリズムを選択してください");
    }

    // 精度目標値チェック
    const accuracyTarget = container.querySelector("#accuracy-target").value;
    if (!accuracyTarget) {
      errors.push("モデル精度目標値を入力してください");
    } else {
      const accuracy = parseFloat(accuracyTarget);
      if (accuracy < 0 || accuracy > 100) {
        errors.push("モデル精度目標値は0-100%の範囲で入力してください");
      }
    }

    // 重み付け合計チェック
    const weightTotal = parseInt(container.querySelector("#weight-total").textContent);
    if (weightTotal !== 100) {
      errors.push("重み付けの合計値は100%にしてください");
    }

    // 季節性パラメータの数値チェック
    const seasonalFactor = container.querySelector("#seasonal-factor").value;
    if (seasonalFactor && isNaN(parseFloat(seasonalFactor))) {
      errors.push("季節性パラメータには数値を入力してください");
    }

    return errors;
  }

  // 4. 登録ボタンのイベントリスナー
  container.querySelector("#model-form").addEventListener("submit", async (e) => {
    e.preventDefault();

    const errors = validateForm();

    // 既存のエラーメッセージを削除
    container.querySelectorAll(".error-message").forEach(el => el.remove());

    if (errors.length > 0) {
      // エラーメッセージを表示
      const errorDiv = document.createElement("div");
      errorDiv.className = "error-message";
      errorDiv.innerHTML = errors.map(err => `• ${err}`).join("<br>");
      container.querySelector(".form-actions").insertBefore(errorDiv, container.querySelector(".form-actions").firstChild);
      return;
    }

    // 既存モデル名重複チェック（新規作成時のみ）
    if (!editingModelId) {
      const modelName = container.querySelector("#model-name").value.trim();
      const existingModels = await window.aivicApi.list(0);
      if (existingModels && existingModels.some(m => m.モデル名 === modelName)) {
        const errorDiv = document.createElement("div");
        errorDiv.className = "error-message";
        errorDiv.textContent = "このモデル名は既に使用されています";
        container.querySelector(".form-actions").insertBefore(errorDiv, container.querySelector(".form-actions").firstChild);
        return;
      }
    }

    const formData = {
      モデル名: container.querySelector("#model-name").value.trim(),
      対象店舗: container.querySelector("#target-store").value,
      商品カテゴリ: Array.from(container.querySelectorAll("#category-checkboxes input[type='checkbox']:checked")).map(cb => cb.value).join(", "),
      学習期間開始日: container.querySelector("#learning-start-date").value,
      学習期間終了日: container.querySelector("#learning-end-date").value,
      予測期間: container.querySelector("input[name='prediction-period']:checked").value + "日",
      データソース: Array.from(container.querySelectorAll("#datasource-checkboxes input[type='checkbox']:checked")).map(cb => cb.value).join(", "),
      アルゴリズム: container.querySelector("#algorithm-type").value,
      学習率: parseFloat(container.querySelector("#learning-rate").value),
      重み付け売上: parseInt(container.querySelector("#weight-sales").value),
      重み付け天候: parseInt(container.querySelector("#weight-weather").value),
      重み付けイベント: parseInt(container.querySelector("#weight-event").value),
      重み付け季節: parseInt(container.querySelector("#weight-season").value),
      季節係数: parseFloat(container.querySelector("#seasonal-factor").value),
      異常値除外: container.querySelector("#exclude-outliers").checked,
      精度目標値: parseFloat(container.querySelector("#accuracy-target").value),
      作成日時: new Date().toISOString()
    };

    let result;
    if (editingModelId) {
      result = await window.aivicApi.update(0, editingModelId, formData);
    } else {
      result = await window.aivicApi.save(0, formData);
    }

    if (result) {
      alert(editingModelId ? "モデル設定が正常に変更されました" : "モデルが正常に作成されました");
      container.querySelector("#model-form-card").classList.add("hidden");
      container.querySelector("#model-form").reset();
      editingModelId = null;

      const rows = await window.aivicApi.list(0);
      if (rows) renderRows(rows);
    }
  });

  // 5. イベントデリゲーション（編集・削除）
  container.addEventListener("click", async (e) => {
    const deleteBtn = e.target.closest(".delete-btn");
    if (deleteBtn) {
      if (!confirm("このモデルを削除しますか？")) return;
      await window.aivicApi.delete(0, deleteBtn.dataset.id);
      const rows = await window.aivicApi.list(0);
      if (rows) renderRows(rows);
      return;
    }

    const editBtn = e.target.closest(".edit-btn");
    if (editBtn) {
      const modelId = editBtn.dataset.id;
      const rows = await window.aivicApi.list(0);
      if (rows) {
        const model = rows.find(r => r.id === modelId);
        if (model) {
          editingModelId = modelId;
          container.querySelector("#form-title").textContent = "モデル設定変更";
          container.querySelector("#btn-save-model").textContent = "保存";

          // フォームに既存データを設定
          container.querySelector("#model-name").value = model.モデル名 || "";
          container.querySelector("#target-store").value = model.対象店舗 || "";

          // 商品カテゴリの設定
          const categories = (model.商品カテゴリ || "").split(", ");
          container.querySelectorAll("#category-checkboxes input[type='checkbox']").forEach(cb => {
            cb.checked = categories.includes(cb.value);
          });

          container.querySelector("#learning-start-date").value = model.学習期間開始日 || "";
          container.querySelector("#learning-end-date").value = model.学習期間終了日 || "";

          // 予測期間の設定
          const period = (model.予測期間 || "").replace("日", "");
          const periodRadio = container.querySelector(`input[name='prediction-period'][value='${period}']`);
          if (periodRadio) periodRadio.checked = true;

          // データソースの設定
          const dataSources = (model.データソース || "").split(", ");
          container.querySelectorAll("#datasource-checkboxes input[type='checkbox']").forEach(cb => {
            cb.checked = dataSources.includes(cb.value);
          });

          container.querySelector("#algorithm-type").value = model.アルゴリズム || "";
          container.querySelector("#learning-rate").value = model.学習率 || 0.01;
          learningRateValue.textContent = model.学習率 || 0.01;

          container.querySelector("#weight-sales").value = model.重み付け売上 || 40;
          container.querySelector("#weight-weather").value = model.重み付け天候 || 20;
          container.querySelector("#weight-event").value = model.重み付けイベント || 20;
          container.querySelector("#weight-season").value = model.重み付け季節 || 20;

          container.querySelector("#seasonal-factor").value = model.季節係数 || 100;
          container.querySelector("#exclude-outliers").checked = model.異常値除外 || false;
          container.querySelector("#accuracy-target").value = model.精度目標値 || "";

          updateWeightTotal();
          container.querySelector("#model-form-card").classList.remove("hidden");
        }
      }
    }
  });

  // CSVエクスポート
  container.querySelector("#btn-csv-export").addEventListener("click", async () => {
    const rows = await window.aivicApi.list(0);
    if (rows) {
      const headers = ["モデル名", "対象店舗", "商品カテゴリ", "アルゴリズム", "精度目標値", "作成日時"];
      const csvContent = "\uFEFF" + [
        headers.join(","),
        ...rows.map(r => [
          `"${r.モデル名 || ""}"`,
          `"${r.対象店舗 || ""}"`,
          `"${r.商品カテゴリ || ""}"`,
          `"${r.アルゴリズム || ""}"`,
          `"${r.精度目標値 || ""}"`,
          `"${r.作成日時 ? new Date(r.作成日時).toLocaleString() : ""}"`
        ].join(","))
      ].join("\n");

      const blob = new Blob([csvContent], { type: "text/csv" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = "model_config_export.csv";
      a.click();
      URL.revokeObjectURL(url);
    }
  });

  // 初期重み付け合計値更新
  updateWeightTotal();
}

