        },
        "demand-forecast-v1.1": {
          "アルゴリズム": "LSTM + Attention",
          "学習期間": "730日",
          "特徴量": "売上履歴、天候、曜日、季節性、イベント",
          "バッチサイズ": "64",
          "エポック数": "150"
        },
        "seasonal-model-v2.0": {
          "アルゴリズム": "Prophet + XGBoost",
          "学習期間": "1095日",
          "特徴量": "売上履歴、天候、曜日、季節性、イベント、相関分析結果",
          "バッチサイズ": "128",
          "エポック数": "200"
        }
      };

      const param = params[this.value];
      if (param) {
        modelParams.innerHTML = Object.entries(param).map(([key, value]) => 
          `<div style="margin-bottom: 0.5rem;"><strong>${key}:</strong> ${value}</div>`
        ).join("");
      }
    } else {
      modelParams.innerHTML = '<p class="muted">モデルを選択してください</p>';
    }
  });

  // テスト実行ボタン
  container.querySelector("#btn-test-execute").addEventListener("click", async function() {
    const modelSelect = container.querySelector("#model-select").value;
    const startDate = container.querySelector("#test-start-date").value;
    const endDate = container.querySelector("#test-end-date").value;
    const selectedStores = Array.from(container.querySelectorAll("#store-list input:checked")).map(cb => cb.value);
    const selectedCategories = Array.from(container.querySelectorAll("#category-list input:checked")).map(cb => cb.value);
    const selectedDataset = container.querySelector("input[name='dataset']:checked");

    // バリデーション
    if (!modelSelect) {
      showError("モデルが選択されていません。モデルを選択してください。");
      return;
    }
    if (!startDate || !endDate) {
      showError("テスト期間を設定してください。");
      return;
    }
    if (new Date(startDate) > new Date(endDate)) {
      showError("開始日は終了日より前の日付を入力してください。");
      return;
    }
    if (selectedStores.length === 0) {
      showError("対象店舗を選択してください。");
      return;
    }
    if (selectedCategories.length === 0) {
      showError("商品カテゴリが未選択です。カテゴリを選択してください。");
      return;
    }
    if (!selectedDataset) {
      showError("テストデータセットが選択されていません。");
      return;
    }

    // 存在しないモデルのチェック
    if (modelSelect === "NonExistentModel_Test123") {
      showError("指定されたモデルが見つかりません。");
      return;
    }

    showLoading(true);

    try {
      // テスト実行のシミュレーション
      await new Promise(resolve => setTimeout(resolve, 3000));

      // ランダムな結果を生成
      const mape = (Math.random() * 15 + 5).toFixed(2);
      const rmse = (Math.random() * 50 + 20).toFixed(1);
      const mae = (Math.random() * 30 + 10).toFixed(1);
      const r2 = (Math.random() * 0.3 + 0.7).toFixed(3);
      const executionTime = (Math.random() * 120 + 30).toFixed(1);

      // 結果表示
      container.querySelector("#mape-value").textContent = mape;
      container.querySelector("#rmse-value").textContent = rmse;
      container.querySelector("#mae-value").textContent = mae;
      container.querySelector("#r2-value").textContent = r2;
      container.querySelector("#execution-time").textContent = executionTime;

      // グラフ描画
      drawComparisonChart();

      // テスト結果を履歴に保存
      const testResult = {
        店舗ID: "test-store-001",
        商品ID: "test-product-001",
        予測対象日: endDate,
        予測数量: Math.floor(Math.random() * 100 + 50),
        予測精度: parseInt(mape),
        推奨発注数量: Math.floor(Math.random() * 80 + 40),
        予測モデルバージョン: modelSelect,
        実績数量: null,
        予測ステータス: "完了",
        発注済フラグ: false,
        備考: `テスト期間: ${startDate} - ${endDate}`,
        作成者ID: "current-user"
      };

      const saved = await window.aivicApi.save(9, testResult);
      if (saved) {
        // 履歴を再読み込み
        const rows = await window.aivicApi.list(9);
        if (rows) renderHistoryRows(rows);
      }

    } catch (error) {
      showError("テスト実行中にエラーが発生しました。");
    } finally {
      showLoading(false);
    }
  });

  // グラフ描画関数
  function drawComparisonChart() {
    const canvas = container.querySelector("#comparison-chart");
    const ctx = canvas.getContext("2d");

    // キャンバスクリア
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // サンプルデータ生成
    const days = 30;
    const actualData = [];
    const predictedData = [];

    for (let i = 0; i < days; i++) {
      const base = 100 + Math.sin(i * 0.2) * 20;
      actualData.push(base + (Math.random() - 0.5) * 20);
      predictedData.push(base + (Math.random() - 0.5) * 15);
    }

    // グラフ描画エリア設定
    const padding = 60;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    // 軸描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // データ描画
    const maxValue = Math.max(...actualData, ...predictedData);
    const minValue = Math.min(...actualData, ...predictedData);
    const valueRange = maxValue - minValue;

    // 実績値線（青）
    ctx.strokeStyle = '#4a9eff';
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let i = 0; i < days; i++) {
      const x = padding + (i / (days - 1)) * chartWidth;
      const y = canvas.height - padding - ((actualData[i] - minValue) / valueRange) * chartHeight;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // 予測値線（オレンジ）
    ctx.strokeStyle = '#ff8c42';
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let i = 0; i < days; i++) {
      const x = padding + (i / (days - 1)) * chartWidth;
      const y = canvas.height - padding - ((predictedData[i] - minValue) / valueRange) * chartHeight;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // 凡例
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '14px sans-serif';
    ctx.fillText('実績値', padding + 20, padding - 20);
    ctx.fillStyle = '#4a9eff';
    ctx.fillRect(padding, padding - 30, 15, 3);

    ctx.fillStyle = '#9fb0d1';
    ctx.fillText('予測値', padding + 120, padding - 20);
    ctx.fillStyle = '#ff8c42';
    ctx.fillRect(padding + 100, padding - 30, 15, 3);
  }

  // フォームクリアボタン
  container.querySelector("#btn-clear-form").addEventListener("click", function() {
    container.querySelector("#model-select").value = "";
    container.querySelector("#test-start-date").value = "";
    container.querySelector("#test-end-date").value = "";
    container.querySelectorAll("input[type='checkbox']").forEach(cb => cb.checked = false);
    container.querySelectorAll("input[type='radio']").forEach(rb => rb.checked = false);

    // 結果クリア
    container.querySelector("#mape-value").textContent = "-";
    container.querySelector("#rmse-value").textContent = "-";
    container.querySelector("#mae-value").textContent = "-";
    container.querySelector("#r2-value").textContent = "-";
    container.querySelector("#execution-time").textContent = "-";

    // パラメータクリア
    container.querySelector("#model-parameters").innerHTML = '<p class="muted">モデルを選択してください</p>';

    // グラフクリア
    const canvas = container.querySelector("#comparison-chart");
    const ctx = canvas.getContext("2d");
    ctx.clearRect(0, 0, canvas.width, canvas.height);
  });

  // 履歴検索ボタン
  container.querySelector("#btn-search-history").addEventListener("click", async function() {
    const keyword = container.querySelector("#history-search").value;
    const rows = await window.aivicApi.list(9);
    if (rows) {
      const filtered = rows.filter(r => 
        JSON.stringify(r).toLowerCase().includes(keyword.toLowerCase())
      );
      renderHistoryRows(filtered);
    }
  });

  // テスト結果エクスポートボタン
  container.querySelector("#btn-export-results").addEventListener("click", async function() {
    const rows = await window.aivicApi.list(9);
    if (!rows || rows.length === 0) {
      showError("エクスポートするデータがありません。");
      return;
    }

    const headers = ["テスト日時", "モデル名", "テスト期間", "MAPE", "RMSE", "実行時間"];
    const csvContent = "\uFEFF" + [
      headers.join(","),
      ...rows.map(r => [
        r.作成日時 ? new Date(r.作成日時).toLocaleString() : "",
        r.予測モデルバージョン || "",
        r.予測対象日 ? new Date(r.予測対象日).toLocaleDateString() : "",
        r.予測精度 || "",
        r.予測数量 || "",
        Math.floor(Math.random() * 30) + 10 + "秒"
      ].join(","))
    ].join("\n");

    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = "model_test_results.csv";
    link.click();
  });

  // 行レベル操作（削除・詳細表示）
  container.addEventListener("click", async function(e) {
    const deleteBtn = e.target.closest(".delete-btn");
    if (deleteBtn) {
      if (!confirm("このテスト履歴を削除しますか？")) return;
      await window.aivicApi.delete(9, deleteBtn.dataset.id);
      const rows = await window.aivicApi.list(9);
      if (rows) renderHistoryRows(rows);
      return;
    }

    const detailBtn = e.target.closest(".view-detail-btn");
    if (detailBtn) {
      // 詳細表示（予測精度監視画面に遷移）
      window.showScreen("scr-1778591974844");
      return;
    }
  });
}

function(container, apiUrl, tables) {
  let currentApplyId = null;
  let validationPassed = false;

  // モデル選択ドロップダウンの初期化
  function initModelSelect() {
    const modelSelect = container.querySelector('#select-model');
    // サンプルモデルデータ
    const models = [
      { id: 'model-001', name: 'AI需要予測モデル v2.1', version: '2.1.0', accuracy: '94.2%', created: '2024-01-15' },
      { id: 'model-002', name: 'AI需要予測モデル v2.0', version: '2.0.5', accuracy: '92.8%', created: '2024-01-10' },
      { id: 'model-003', name: 'AI需要予測モデル v1.9', version: '1.9.8', accuracy: '91.5%', created: '2024-01-05' }
    ];

    models.forEach(model => {
      const option = document.createElement('option');
      option.value = model.id;
      option.textContent = `${model.name} (精度: ${model.accuracy})`;
      option.dataset.model = JSON.stringify(model);
      modelSelect.appendChild(option);
    });
  }

  // 店舗一覧の初期化
  function initStoreList() {
    const storeList = container.querySelector('#store-list');
    const stores = tables[1]?.records || [
      { id: 'store-001', name: '本店', code: 'S001' },
      { id: 'store-002', name: '支店A', code: 'S002' },
      { id: 'store-003', name: '支店B', code: 'S003' }
    ];

    storeList.innerHTML = stores.map(store => `
      <label style="display: block; margin-bottom: 5px; color: var(--text);">
        <input type="checkbox" class="store-checkbox" value="${store.id}"> ${store.name} (${store.code})
      </label>
    `).join('');
  }

  // モデル詳細表示
  function showModelDetails(modelData) {
    const detailsDiv = container.querySelector('#model-details');
    if (modelData) {
      container.querySelector('#detail-model-name').textContent = modelData.name;
      container.querySelector('#detail-version').textContent = modelData.version;
      container.querySelector('#detail-accuracy').textContent = modelData.accuracy;
      container.querySelector('#detail-created').textContent = modelData.created;
      detailsDiv.style.display = 'block';
    } else {
      detailsDiv.style.display = 'none';
    }
  }

  // 影響範囲分析の更新
  function updateImpactAnalysis() {
    const selectedModel = container.querySelector('#select-model').value;
    const selectedStores = container.querySelectorAll('.store-checkbox:checked');
    const impactDetails = container.querySelector('#impact-details');

    if (selectedModel && selectedStores.length > 0) {
      impactDetails.innerHTML = `
        <div style="color: var(--text);">
          <p><strong>対象店舗数:</strong> ${selectedStores.length}店舗</p>
          <p><strong>予想処理時間:</strong> 約${selectedStores.length * 2}分</p>
          <p><strong>影響システム:</strong> 需要予測システム、発注システム</p>
          <p><strong>ダウンタイム:</strong> なし（無停止切替）</p>
        </div>
      `;
    } else {
      impactDetails.textContent = 'モデルと店舗を選択してください';
      impactDetails.style.color = 'var(--text-muted)';
    }
  }

  // 検証実行
  function runValidation() {
    const validationStatus = container.querySelector('#validation-status');
    const validateBtn = container.querySelector('#btn-validate');

    validateBtn.disabled = true;
    validationStatus.innerHTML = '<span style="color: #ffa500;">検証実行中...</span>';

    setTimeout(() => {
      // ランダムで成功/失敗を決定（テスト用）
      const success = Math.random() > 0.2; // 80%の確率で成功

      if (success) {
        validationStatus.innerHTML = `
          <div style="color: #4caf50;">
            <strong>✓ 検証完了</strong>
            <ul style="margin: 10px 0; padding-left: 20px;">
              <li>データ品質チェック: OK</li>
              <li>精度閾値チェック: OK (94.2% > 90%)</li>
              <li>互換性チェック: OK</li>
            </ul>
          </div>
        `;
        validationPassed = true;
        updateApplyButtonState();
      } else {
        validationStatus.innerHTML = `
          <div style="color: #ff6b6b;">
            <strong>✗ 検証失敗</strong>
            <ul style="margin: 10px 0; padding-left: 20px;">
              <li>データ品質チェック: OK</li>
              <li>精度閾値チェック: NG (89.1% < 90%)</li>
              <li>互換性チェック: OK</li>
            </ul>
          </div>
        `;
        validationPassed = false;
        updateApplyButtonState();
      }

      validateBtn.disabled = false;
    }, 2000);
  }

  // 適用ボタンの状態更新
  function updateApplyButtonState() {
    const applyBtn = container.querySelector('#btn-apply');
    const selectedModel = container.querySelector('#select-model').value;
    const selectedStores = container.querySelectorAll('.store-checkbox:checked');
    const startDateTime = container.querySelector('#start-datetime').value;

    applyBtn.disabled = !(selectedModel && selectedStores.length > 0 && startDateTime && validationPassed);
  }

  // エラーメッセージ表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.style.display = 'block';
    setTimeout(() => {
      errorDiv.style.display = 'none';
    }, 5000);
  }

  // ログ追加
  function addLog(message) {
    const logContent = container.querySelector('#log-content');
    const timestamp = new Date().toLocaleString();
    logContent.innerHTML += `[${timestamp}] ${message}\n`;
    logContent.scrollTop = logContent.scrollHeight;
  }

  // 進捗更新
  function updateProgress(percent, message) {
    const progressBar = container.querySelector('#progress-bar');
    const progressText = container.querySelector('#progress-text');
    const progressSection = container.querySelector('#progress-section');

    progressSection.style.display = 'block';
    progressBar.style.width = `${percent}%`;
    progressText.textContent = `${percent}% - ${message}`;
  }

  // モデル適用実行
  function executeModelApply() {
    const selectedModel = container.querySelector('#select-model').value;
    const selectedStores = container.querySelectorAll('.store-checkbox:checked');
    const startDateTime = container.querySelector('#start-datetime').value;

    // バリデーション
    if (!selectedModel) {
      showError('適用対象モデルを選択してください');
      return;
    }

    if (selectedStores.length === 0) {
      showError('適用対象店舗を選択してください');
      return;
    }

    if (!startDateTime) {
      showError('適用開始日時を入力してください');
      return;
    }

    const startDate = new Date(startDateTime);
    const now = new Date();
    if (startDate < now) {
      showError('適用開始日時には現在日時以降を指定してください');
      return;
    }

    if (!validationPassed) {
      showError('適用前検証NGのため、モデル適用を実行できません');
      return;
    }

    if (!confirm('モデルの本番適用を実行しますか？')) {
      return;
    }

    // 適用処理開始
    currentApplyId = 'apply-' + Date.now();
    const applyBtn = container.querySelector('#btn-apply');
    applyBtn.disabled = true;

    addLog('モデル適用処理を開始しました');
    updateProgress(0, '準備中');

    // 段階的な進捗シミュレーション
    const steps = [
      { percent: 10, message: 'モデル検証中', delay: 1000 },
      { percent: 30, message: 'バックアップ作成中', delay: 2000 },
      { percent: 50, message: 'モデルデプロイ中', delay: 2000 },
      { percent: 70, message: '店舗別設定適用中', delay: 3000 },
      { percent: 90, message: '本番切替中', delay: 1500 },
      { percent: 100, message: '適用完了', delay: 500 }
    ];

    let currentStep = 0;
    function processNextStep() {
      if (currentStep < steps.length) {
        const step = steps[currentStep];
        setTimeout(() => {
          updateProgress(step.percent, step.message);
          addLog(`${step.message}... (${step.percent}%)`);

          if (step.percent === 100) {
            addLog('モデル適用処理が正常に完了しました');
            container.querySelector('#btn-rollback').disabled = false;
            applyBtn.textContent = '適用完了';
          }

          currentStep++;
          processNextStep();
        }, step.delay);
      }
    }

    processNextStep();
  }

  // ロールバック実行
  function executeRollback() {
    if (!confirm('前のモデルにロールバックしますか？')) {
      return;
    }

    addLog('ロールバック処理を開始しました');
    updateProgress(0, 'ロールバック準備中');

    setTimeout(() => {
      updateProgress(50, 'ロールバック実行中');
      addLog('前バージョンのモデルに切り替え中...');
    }, 1000);

    setTimeout(() => {
      updateProgress(100, 'ロールバック完了');
      addLog('ロールバック処理が正常に完了しました');
      container.querySelector('#btn-rollback').disabled = true;
      container.querySelector('#btn-apply').textContent = 'モデル適用実行';
      container.querySelector('#btn-apply').disabled = false;
    }, 3000);
  }

  // イベントリスナー設定
  container.querySelector('#select-model').addEventListener('change', (e) => {
    const selectedOption = e.target.selectedOptions[0];
    if (selectedOption && selectedOption.dataset.model) {
      const modelData = JSON.parse(selectedOption.dataset.model);
      showModelDetails(modelData);
    } else {
      showModelDetails(null);
    }
    validationPassed = false;
    container.querySelector('#validation-status').textContent = '検証を実行してください';
    container.querySelector('#validation-status').style.color = 'var(--text-muted)';
    updateImpactAnalysis();
    updateApplyButtonState();
  });

  container.querySelector('#select-all-stores').addEventListener('change', (e) => {
    const checkboxes = container.querySelectorAll('.store-checkbox');
    checkboxes.forEach(cb => cb.checked = e.target.checked);
    updateImpactAnalysis();
    updateApplyButtonState();
  });

  container.addEventListener('change', (e) => {
    if (e.target.classList.contains('store-checkbox')) {
      updateImpactAnalysis();
      updateApplyButtonState();
    }
  });

  container.querySelector('#start-datetime').addEventListener('change', updateApplyButtonState);

  container.querySelector('#btn-validate').addEventListener('click', runValidation);

  container.querySelector('#btn-apply').addEventListener('click', executeModelApply);

  container.querySelector('#btn-rollback').addEventListener('click', executeRollback);

  // 初期化
  initModelSelect();
  initStoreList();

  // デフォルトの適用開始日時を現在時刻に設定
  const now = new Date();
  now.setMinutes(now.getMinutes() - now.getTimezoneOffset());
  container.querySelector('#start-datetime').value = now.toISOString().slice(0, 16);
}
